141	// Stop cancels the heartbeat and waits for its goroutine to exit.
142	func (h *Heartbeat) Stop() {
143		if h == nil {
144			return
145		}
146	
147		h.once.Do(func() {
148			if h.stop != nil {
149				close(h.stop)
150			}
