217	// NewRouter constructs the routing runtime on top of a peer registry.
218	func NewRouter(
219		peers *PeerRegistry,
220		transport RouterTransport,
221		maxReplayAge time.Duration,
222		opts ...RouterOption,
223	) (*Router, error) {
224		if peers == nil {
225			return nil, fmt.Errorf("%w: peer registry is required", ErrInvalidField)
226		}
227		if maxReplayAge <= 0 {
228			maxReplayAge = DefaultMaxReplayAge
229		}
230	
231		router := &Router{
232			peers:          peers,
233			transport:      transport,
234			activationTopK: defaultRouterActivationTopK,
235			maxReplayAge:   maxReplayAge,
236			now:            func() time.Time { return time.Now().UTC() },
237			seen:           make(map[string]time.Time),
238			works:          make(map[string]Work),
239		}
240		for _, opt := range opts {
241			if opt != nil {
242				opt(router)
243			}
244		}
245		if router.now == nil {
246			router.now = func() time.Time { return time.Now().UTC() }
247		}
248		if router.activationTopK <= 0 {
249			router.activationTopK = defaultRouterActivationTopK
250		}
251	
252		return router, nil
253	}
