263	// PublishGreet advertises one local peer card to its joined channel.
264	func (r *Router) PublishGreet(ctx context.Context, sessionID string, summary string) (SendResult, error) {
265		if r == nil || r.peers == nil {
266			return SendResult{}, fmt.Errorf("%w: router peer registry is required", ErrInvalidField)
267		}
268	
269		local, ok := r.peers.LocalBySession(sessionID)
270		if !ok {
271			return SendResult{}, fmt.Errorf("%w: session=%q", ErrLocalPeerNotFound, strings.TrimSpace(sessionID))
272		}
273	
274		body, err := json.Marshal(GreetBody{
275			PeerCard: clonePeerCard(local.PeerCard),
276			Summary:  ResolveGreetSummary(local.PeerCard, summary),
277		})
278		if err != nil {
279			return SendResult{}, fmt.Errorf("network: marshal greet body: %w", err)
280		}
281	
282		return r.Send(ctx, SendRequest{
283			SessionID:   local.SessionID,
284			WorkspaceID: local.WorkspaceID,
285			Channel:     local.Channel,
286			Kind:        KindGreet,
287			Body:        body,
288		})
289	}
