291	// StartHeartbeat publishes greet immediately, then keeps re-greeting on the configured interval.
292	func (r *Router) StartHeartbeat(ctx context.Context, sessionID string, summary string) (*Heartbeat, error) {
293		if ctx == nil {
294			return nil, errors.New("network: heartbeat context is required")
295		}
296		if r == nil || r.peers == nil {
297			return nil, fmt.Errorf("%w: router peer registry is required", ErrInvalidField)
298		}
299	
300		interval := r.peers.GreetInterval()
301		if interval <= 0 {
302			return nil, fmt.Errorf("%w: greet interval must be positive", ErrInvalidField)
303		}
304		if _, err := r.PublishGreet(ctx, sessionID, summary); err != nil {
305			return nil, err
306		}
307	
308		heartbeat := &Heartbeat{
309			stop: make(chan struct{}),
310			done: make(chan struct{}),
311		}
312	
313		go func() {
314			defer close(heartbeat.done)
315	
316			ticker := time.NewTicker(interval)
317			defer ticker.Stop()
318	
319			for {
320				select {
321				case <-heartbeat.stop:
322					return
323				case <-ctx.Done():
324					return
325				case <-ticker.C:
326					if _, err := r.PublishGreet(
327						ctx,
328						sessionID,
329						summary,
330					); err != nil &&
331						errors.Is(err, ErrLocalPeerNotFound) {
332						return
333					}
334				}
335			}
336		}()
337	
338		return heartbeat, nil
339	}
