341	// PrepareSend validates one outbound request and computes the publish subject
342	// without performing transport side effects.
343	func (r *Router) PrepareSend(ctx context.Context, req SendRequest) (SendResult, error) {
344		if ctx == nil {
345			return SendResult{}, errors.New("network: send context is required")
346		}
347		if r == nil {
348			return SendResult{}, errors.New("network: router is required")
349		}
350		if err := ctx.Err(); err != nil {
351			return SendResult{}, err
352		}
353	
354		now := r.now().UTC()
355		envelope, err := r.buildEnvelope(req, now)
356		if err != nil {
357			return SendResult{}, err
358		}
359		if envelope.IsDirected() && !r.peers.HasPresence(envelope.WorkspaceID, envelope.Channel, *envelope.To, now) {
360			return SendResult{}, fmt.Errorf(
361				"%w: peer_id=%q channel=%q",
362				ErrTargetPeerNotFound,
363				*envelope.To,
364				envelope.Channel,
365			)
366		}
367		if err := r.validateSendLifecycle(envelope, now); err != nil {
368			return SendResult{}, err
369		}
370	
371		subject, err := subjectForEnvelope(envelope)
372		if err != nil {
373			return SendResult{}, err
374		}
375	
376		return SendResult{
377			ID:       envelope.ID,
378			Subject:  subject,
379			Envelope: envelope,
380		}, nil
381	}
