383	// PublishPrepared publishes a previously prepared envelope and syncs the local
384	// lifecycle cache only after the transport accepts the publish.
385	func (r *Router) PublishPrepared(ctx context.Context, prepared SendResult) (SendResult, error) {
386		if ctx == nil {
387			return SendResult{}, errors.New("network: send context is required")
388		}
389		if r == nil {
390			return SendResult{}, errors.New("network: router is required")
391		}
392		if err := ctx.Err(); err != nil {
393			return SendResult{}, err
394		}
395	
396		envelope := prepared.Envelope
397		subject := strings.TrimSpace(prepared.Subject)
398		if subject == "" {
399			var err error
400			subject, err = subjectForEnvelope(envelope)
401			if err != nil {
402				return SendResult{}, err
403			}
404		}
405		if err := r.publishEnvelope(ctx, envelope); err != nil {
406			return SendResult{}, err
407		}
408		r.syncSentLifecycle(envelope, time.Unix(envelope.TS, 0).UTC())
409	
410		return SendResult{
411			ID:       envelope.ID,
412			Subject:  subject,
413			Envelope: envelope,
414		}, nil
415	}
