426	// Receive validates one inbound envelope, updates presence, and returns delivery decisions.
427	func (r *Router) Receive(ctx context.Context, payload []byte) (RouteResult, error) {
428		if ctx == nil {
429			return RouteResult{}, errors.New("network: receive context is required")
430		}
431		if r == nil {
432			return RouteResult{}, errors.New("network: router is required")
433		}
434	
435		now := r.now().UTC()
436		envelope, err := ParseEnvelope(payload, ValidateOptions{Now: now, MaxReplayAge: r.maxReplayAge})
437		if err != nil {
438			return r.handleReceiveParseError(ctx, payload, now, err)
439		}
440	
441		state, done, err := r.prepareReceiveState(ctx, envelope, now)
442		if err != nil {
443			return RouteResult{}, err
444		}
445		if done {
446			return state.result, nil
447		}
448		return r.dispatchReceivedEnvelope(ctx, &state)
449	}
