451	func (r *Router) handleReceiveParseError(
452		ctx context.Context,
453		payload []byte,
454		now time.Time,
455		parseErr error,
456	) (RouteResult, error) {
457		reason := reasonCodeForReceiveError(parseErr)
458		result := RouteResult{
459			Rejected:   true,
460			ReasonCode: &reason,
461		}
462		partial := parseEnvelopeSummary(payload)
463		if partial == nil {
464			return result, nil
465		}
466		result.Envelope = partial
467		if !shouldEmitWorkReceipt(*partial) {
468			return result, nil
469		}
470	
471		directedTarget, ok, err := r.resolveDirectedTarget(*partial)
472		if err != nil {
473			return RouteResult{}, err
474		}
475		if !ok {
476			return result, nil
477		}
478		status, emit := rejectionReceiptStatus(reason)
479		result, _, err = r.appendPublishedReceipt(ctx, result, directedTarget, *partial, now, status, emit)
480		return result, err
481	}
