483	func (r *Router) prepareReceiveState(
484		ctx context.Context,
485		envelope Envelope,
486		now time.Time,
487	) (receiveState, bool, error) {
488		state := receiveState{
489			result:   RouteResult{Envelope: &envelope},
490			envelope: envelope,
491			now:      now,
492		}
493		directedTarget, ok, err := r.resolveDirectedTarget(envelope)
494		if err != nil {
495			return receiveState{}, false, err
496		}
497		state.directedTarget = directedTarget
498		state.hasDirectedTarget = ok
499		if envelope.IsDirected() && !ok {
500			reason := ReasonCodeNotTarget
501			state.result.Rejected = true
502			state.result.ReasonCode = &reason
503			return state, true, nil
504		}
505		if !r.markSeen(envelope, now) {
506			return state, false, nil
507		}
508	
509		reason := ReasonCodeDuplicate
510		state.result.Duplicate = true
511		state.result.Rejected = true
512		state.result.ReasonCode = &reason
513		if !shouldEmitWorkReceipt(envelope) || !ok {
514			return state, true, nil
515		}
516	
517		result, _, err := r.appendPublishedReceipt(
518			ctx,
519			state.result,
520			directedTarget,
521			envelope,
522			now,
523			ReceiptStatusDuplicate,
524			true,
525		)
526		if err != nil {
527			return receiveState{}, false, err
528		}
529		state.result = result
530		return state, true, nil
531	}
