533	func (r *Router) dispatchReceivedEnvelope(ctx context.Context, state *receiveState) (RouteResult, error) {
534		switch state.envelope.Kind {
535		case KindGreet:
536			return r.handleReceivedGreet(state)
537		case KindWhois:
538			return r.handleWhois(
539				ctx,
540				state.envelope,
541				state.result,
542				state.directedTarget,
543				state.hasDirectedTarget,
544				state.now,
545			)
546		case KindSay:
547			return r.handleReceivedSay(ctx, state)
548		case KindCapability:
549			return r.handleReceivedCapability(ctx, state)
550		case KindReceipt, KindTrace:
551			return r.handleReceivedLifecycle(ctx, state)
552		default:
553			reason := ReasonCodeUnsupportedKind
554			state.result.Rejected = true
555			state.result.ReasonCode = &reason
556			return state.result, nil
557		}
558	}
