560	func (r *Router) handleReceivedGreet(state *receiveState) (RouteResult, error) {
561		body, err := decodeReceivedBody[GreetBody](state.envelope, "greet")
562		if err != nil {
563			return RouteResult{}, err
564		}
565		refresh, refreshErr := r.peers.RefreshRemoteDetailed(
566			state.envelope.WorkspaceID,
567			state.envelope.Channel,
568			body.PeerCard,
569			nil,
570			false,
571			state.now,
572		)
573		if refreshErr != nil {
574			return RouteResult{}, refreshErr
575		}
576		state.result.PeerEvents = append(
577			state.result.PeerEvents,
578			peerLifecycleEventsFromExpired(refresh.Expired, state.now, r.peers.GreetInterval())...,
579		)
580		if refresh.Joined {
581			state.result.PeerEvents = append(
582				state.result.PeerEvents,
583				PeerLifecycleEvent{
584					Kind:      PeerLifecycleJoined,
585					Peer:      peerInfoFromRemote(refresh.Entry, state.now, r.peers.GreetInterval()),
586					Timestamp: state.now,
587				},
588			)
589		}
590		return state.result, nil
591	}
592	
593	func peerLifecycleEventsFromExpired(
594		expired []RemotePeerEntry,
595		at time.Time,
596		greetInterval time.Duration,
597	) []PeerLifecycleEvent {
598		if len(expired) == 0 {
599			return nil
600		}
601		events := make([]PeerLifecycleEvent, 0, len(expired))
602		for _, entry := range expired {
603			peer := peerInfoFromRemote(entry, at, greetInterval)
604			peer.PresenceState = PresenceStateExpired
605			events = append(events, PeerLifecycleEvent{
606				Kind:      PeerLifecycleLeft,
607				Peer:      peer,
608				Timestamp: at,
609			})
610		}
611		return events
612	}
