614	func (r *Router) handleReceivedSay(ctx context.Context, state *receiveState) (RouteResult, error) {
615		result := state.result
616		deliver := true
617		if state.envelope.WorkID != nil {
618			var err error
619			result, deliver, err = r.applyReceiveLifecycle(ctx, state, true)
620			if err != nil {
621				return RouteResult{}, err
622			}
623		}
624		if !deliver {
625			return result, nil
626		}
627		if state.envelope.IsDirected() {
628			if delivery, ok := deliveryFromLocalPeer(state.directedTarget, state.envelope); ok {
629				result.Deliveries = []Delivery{delivery}
630			}
631			return result, nil
632		}
633		deliveries, err := r.deliveriesFromLocalPeers(ctx, state.envelope)
634		if err != nil {
635			return RouteResult{}, err
636		}
637		result.Deliveries = deliveries
638		return result, nil
639	}
