663	func (r *Router) handleReceivedLifecycle(ctx context.Context, state *receiveState) (RouteResult, error) {
664		result, deliver, err := r.applyReceiveLifecycle(ctx, state, true)
665		if err != nil {
666			return RouteResult{}, err
667		}
668		if deliver {
669			if delivery, ok := deliveryFromLocalPeer(state.directedTarget, state.envelope); ok {
670				result.Deliveries = []Delivery{delivery}
671			}
672		}
673		return result, nil
674	}
