676	func (r *Router) applyReceiveLifecycle(
677		ctx context.Context,
678		state *receiveState,
679		emitRejectionReceipt bool,
680	) (RouteResult, bool, error) {
681		result := state.result
682		if state.envelope.WorkID == nil {
683			return result, true, nil
684		}
685	
686		lifecycleResult, err := r.applyLifecycle(state.envelope, state.now)
687		switch {
688		case err == nil:
689			switch lifecycleResult.Action {
690			case LifecycleActionIgnored:
691				result.Ignored = true
692				return result, false, nil
693			case LifecycleActionRejectWork:
694				reason := ReasonCodeWorkClosed
695				if lifecycleResult.ReasonCode != nil {
696					reason = *lifecycleResult.ReasonCode
697				}
698				result.Rejected = true
699				result.ReasonCode = &reason
700				if !emitRejectionReceipt || !shouldEmitWorkReceipt(state.envelope) {
701					return result, false, nil
702				}
703				return r.appendPublishedReceipt(
704					ctx,
705					result,
706					state.directedTarget,
707					state.envelope,
708					state.now,
709					ReceiptStatusRejected,
710					true,
711				)
712			default:
713				return result, true, nil
714			}
715		case errors.Is(err, ErrWorkContainerMismatch):
716			reason := ReasonCodeWorkContainerMismatch
717			result.Rejected = true
718			result.ReasonCode = &reason
719			if !emitRejectionReceipt || !shouldEmitWorkReceipt(state.envelope) {
720				return result, false, nil
721			}
722			return r.appendPublishedReceipt(
723				ctx,
724				result,
725				state.directedTarget,
726				state.envelope,
727				state.now,
728				ReceiptStatusRejected,
729				true,
730			)
731		case errors.Is(err, ErrWorkActorNotAllowed),
732			errors.Is(err, ErrWorkNotFound):
733			result.Ignored = true
734			return result, false, nil
735		case errors.Is(err, ErrInvalidStateTransition):
736			reason := ReasonCodeInternal
737			result.Rejected = true
738			result.ReasonCode = &reason
739			return result, false, nil
740		default:
741			return RouteResult{}, false, err
742		}
743	}
