785	func (r *Router) handleWhois(
786		ctx context.Context,
787		envelope Envelope,
788		result RouteResult,
789		directedTarget LocalPeer,
790		hasDirectedTarget bool,
791		now time.Time,
792	) (RouteResult, error) {
793		body, err := envelope.DecodeBody()
794		if err != nil {
795			return RouteResult{}, err
796		}
797		whois, ok := body.(WhoisBody)
798		if !ok {
799			return RouteResult{}, fmt.Errorf("network: unexpected whois body type %T", body)
800		}
801	
802		switch whois.Type {
803		case WhoisTypeResponse:
804			if whois.PeerCard != nil {
805				capabilityCatalog, capabilityCatalogKnown := decodeWhoisCapabilityCatalogResponseExt(envelope.Ext)
806				if _, _, refreshErr := r.peers.RefreshRemoteWithCapabilityCatalog(
807					envelope.WorkspaceID,
808					envelope.Channel,
809					*whois.PeerCard,
810					capabilityCatalog,
811					capabilityCatalogKnown,
812					now,
813				); refreshErr != nil {
814					return RouteResult{}, refreshErr
815				}
816			}
817			if hasDirectedTarget {
818				if delivery, ok := deliveryFromLocalPeer(directedTarget, envelope); ok {
819					result.Deliveries = []Delivery{delivery}
820				}
821			}
822			return result, nil
823		case WhoisTypeRequest:
824			return r.handleWhoisRequest(ctx, envelope, result, whois, directedTarget, hasDirectedTarget, now)
825		default:
826			reason := ReasonCodeMalformed
827			result.Rejected = true
828			result.ReasonCode = &reason
829			return result, nil
830		}
831	}
