833	func (r *Router) handleWhoisRequest(
834		ctx context.Context,
835		envelope Envelope,
836		result RouteResult,
837		whois WhoisBody,
838		directedTarget LocalPeer,
839		hasDirectedTarget bool,
840		now time.Time,
841	) (RouteResult, error) {
842		discoveryRequest := parseWhoisCapabilityDiscoveryRequest(envelope.Ext)
843		if envelope.IsDirected() && hasDirectedTarget && isEnvelopeSender(directedTarget, envelope) {
844			result.Ignored = true
845			return result, nil
846		}
847		responders := r.whoisRequestResponders(envelope, whois, directedTarget, hasDirectedTarget)
848	
849		for _, responder := range responders {
850			reply, err := r.buildWhoisResponseEnvelope(envelope, responder, discoveryRequest, now)
851			if err != nil {
852				return RouteResult{}, err
853			}
854			result.Generated = append(result.Generated, reply)
855		}
856		if len(result.Generated) > 0 {
857			if err := r.publishGenerated(ctx, result.Generated); err != nil {
858				return RouteResult{}, err
859			}
860		}
861		return result, nil
862	}
