864	func (r *Router) whoisRequestResponders(
865		envelope Envelope,
866		whois WhoisBody,
867		directedTarget LocalPeer,
868		hasDirectedTarget bool,
869	) []LocalPeer {
870		if envelope.IsDirected() {
871			if hasDirectedTarget && !isEnvelopeSender(directedTarget, envelope) {
872				return []LocalPeer{directedTarget}
873			}
874			return nil
875		}
876		matches := r.peers.MatchLocalPeers(envelope.WorkspaceID, envelope.Channel, whois.Query)
877		responders := make([]LocalPeer, 0, len(matches))
878		for _, peer := range matches {
879			if isEnvelopeSender(peer, envelope) {
880				continue
881			}
882			responders = append(responders, peer)
883		}
884		return responders
885	}
