887	func (r *Router) buildWhoisResponseEnvelope(
888		request Envelope,
889		responder LocalPeer,
890		discoveryRequest whoisCapabilityDiscoveryRequest,
891		now time.Time,
892	) (Envelope, error) {
893		responseCard := clonePeerCard(responder.PeerCard)
894		if len(responder.CapabilityCatalog) != 0 {
895			responseCatalog := responder.CapabilityCatalog
896			if discoveryRequest.includeCapabilityCatalog {
897				responseCatalog = selectWhoisCapabilityCatalog(
898					responder.CapabilityCatalog,
899					discoveryRequest.capabilityIDs,
900				)
901			}
902			if err := applyCapabilityBriefProjection(&responseCard, responseCatalog); err != nil {
903				return Envelope{}, err
904			}
905		}
906	
907		payload, err := marshalEnvelopeBody(WhoisBody{
908			Type:     WhoisTypeResponse,
909			PeerCard: &responseCard,
910		})
911		if err != nil {
912			return Envelope{}, err
913		}
914		responseExt, err := buildWhoisCapabilityCatalogResponseExt(
915			discoveryRequest,
916			responder.CapabilityCatalog,
917		)
918		if err != nil {
919			return Envelope{}, err
920		}
921	
922		reply := Envelope{
923			Protocol:    ProtocolV0,
924			ID:          store.NewID("msg"),
925			WorkspaceID: request.WorkspaceID,
926			Kind:        KindWhois,
927			Channel:     request.Channel,
928			From:        responder.PeerID,
929			To:          ptrString(request.From),
930			ReplyTo:     ptrString(request.ID),
931			TS:          now.Unix(),
932			Body:        payload,
933			Proof:       nil,
934			Ext:         responseExt,
935		}
936		if err := ValidateEnvelope(reply, ValidateOptions{Now: now, MaxReplayAge: r.maxReplayAge}); err != nil {
937			return Envelope{}, err
938		}
939		if err := ensureEnvelopeSizeLimit(reply); err != nil {
940			return Envelope{}, err
941		}
942		return reply, nil
943	}
