945	func (r *Router) buildEnvelope(req SendRequest, now time.Time) (Envelope, error) {
946		if r.peers == nil {
947			return Envelope{}, fmt.Errorf("%w: peer registry is required", ErrInvalidField)
948		}
949	
950		sessionID := strings.TrimSpace(req.SessionID)
951		if sessionID == "" {
952			return Envelope{}, fmt.Errorf("%w: session is required", ErrMissingField)
953		}
954	
955		local, ok := r.peers.LocalBySession(sessionID)
956		if !ok {
957			return Envelope{}, fmt.Errorf("%w: session=%q", ErrLocalPeerNotFound, sessionID)
958		}
959	
960		channel := strings.TrimSpace(req.Channel)
961		if channel == "" {
962			return Envelope{}, fmt.Errorf("%w: channel is required", ErrMissingField)
963		}
964		if local.Channel != channel {
965			return Envelope{}, fmt.Errorf("%w: session=%q channel=%q", ErrLocalPeerNotFound, sessionID, channel)
966		}
967		if reqWorkspaceID := strings.TrimSpace(
968			req.WorkspaceID,
969		); reqWorkspaceID != "" &&
970			reqWorkspaceID != local.WorkspaceID {
971			return Envelope{}, fmt.Errorf(
972				"%w: session=%q workspace_id=%q",
973				ErrLocalPeerNotFound,
974				sessionID,
975				reqWorkspaceID,
976			)
977		}
978	
979		id := normalizeOptionalIdentifier(req.ID)
980		if id == nil {
981			id = ptrString(store.NewID("msg"))
982		}
983		envelope := Envelope{
984			Protocol:    ProtocolV0,
985			ID:          *id,
986			WorkspaceID: local.WorkspaceID,
987			Kind:        Kind(strings.TrimSpace(string(req.Kind))),
988			Channel:     channel,
989			Surface:     normalizeOptionalSurface(req.Surface),
990			ThreadID:    normalizeOptionalIdentifier(req.ThreadID),
991			DirectID:    normalizeOptionalIdentifier(req.DirectID),
992			From:        local.PeerID,
993			To:          normalizeOptionalIdentifier(req.To),
994			Mentions:    normalizeEnvelopeMentions(req.Mentions),
995			WorkID:      normalizeOptionalIdentifier(req.WorkID),
996			ReplyTo:     normalizeOptionalIdentifier(req.ReplyTo),
997			TraceID:     normalizeOptionalIdentifier(req.TraceID),
998			CausationID: normalizeOptionalIdentifier(req.CausationID),
999			TS:          now.Unix(),
1000			ExpiresAt:   cloneInt64Ptr(req.ExpiresAt),
1001			Body:        cloneRawMessage(req.Body),
1002			Ext:         cloneExtensionMap(req.Ext),
1003		}
1004	
1005		if isConversationKind(envelope.Kind) &&
1006			envelope.Surface != nil &&
1007			*envelope.Surface == SurfaceDirect &&
1008			envelope.To != nil {
1009			directID, _, _, err := DirectRoomIdentity(envelope.WorkspaceID, channel, envelope.From, *envelope.To)
1010			if err != nil {
1011				return Envelope{}, err
1012			}
1013			envelope.DirectID = ptrString(directID)
1014		}
1015	
1016		if err := ValidateEnvelope(envelope, ValidateOptions{Now: now, MaxReplayAge: r.maxReplayAge}); err != nil {
1017			return Envelope{}, err
1018		}
1019		return envelope, nil
1020	}
