1037	func (r *Router) markSeen(envelope Envelope, now time.Time) bool {
1038		r.mu.Lock()
1039		defer r.mu.Unlock()
1040	
1041		for id, expiresAt := range r.seen {
1042			if !expiresAt.After(now) {
1043				delete(r.seen, id)
1044			}
1045		}
1046		if expiresAt, ok := r.seen[envelope.ID]; ok && expiresAt.After(now) {
1047			return true
1048		}
1049		r.seen[envelope.ID] = replayDeadline(envelope, now, r.maxReplayAge)
1050		return false
1051	}
