1188	func replayDeadline(envelope Envelope, now time.Time, maxReplayAge time.Duration) time.Time {
1189		deadline := time.Unix(envelope.TS, 0).Add(maxReplayAge).UTC()
1190		if envelope.ExpiresAt != nil {
1191			expiresAt := time.Unix(*envelope.ExpiresAt, 0).UTC()
1192			if expiresAt.Before(deadline) {
1193				deadline = expiresAt
1194			}
1195		}
1196		minDeadline := time.Unix(now.Unix()+1, 0).UTC()
1197		if deadline.Before(minDeadline) {
1198			return minDeadline
1199		}
1200		return deadline
1201	}
