1228	func (r *Router) deliveriesFromLocalPeers(ctx context.Context, envelope Envelope) ([]Delivery, error) {
1229		peers := r.peers.LocalPeers(envelope.WorkspaceID, envelope.Channel)
1230		if !envelopeRequiresThreadParticipantRouting(envelope) {
1231			return deliveriesFromLocalPeers(peers, envelope), nil
1232		}
1233		mentioned := mentionedPeerSet(envelope)
1234		if r.threadParticipants == nil {
1235			return r.selectEmptyThreadDeliveries(ctx, peers, envelope, nil, mentioned)
1236		}
1237		participants, err := r.threadParticipantSet(ctx, envelope)
1238		if err != nil {
1239			return nil, err
1240		}
1241		if len(participants) == 0 {
1242			return r.selectEmptyThreadDeliveries(ctx, peers, envelope, nil, mentioned)
1243		}
1244		filtered := make([]LocalPeer, 0, len(peers))
1245		for _, peer := range peers {
1246			peerID := strings.TrimSpace(peer.PeerID)
1247			if participants[peerID] || mentioned[peerID] {
1248				filtered = append(filtered, peer)
1249			}
1250		}
1251		return deliveriesFromLocalPeers(filtered, envelope), nil
1252	}
