1254	func (r *Router) selectEmptyThreadDeliveries(
1255		ctx context.Context,
1256		peers []LocalPeer,
1257		envelope Envelope,
1258		participants map[string]bool,
1259		mentioned map[string]bool,
1260	) ([]Delivery, error) {
1261		decision, err := r.selectEmptyThreadPeers(ctx, peers, envelope, participants, mentioned)
1262		if err != nil {
1263			return nil, err
1264		}
1265		deliveries := deliveriesFromLocalPeers(decision.fullPeers, envelope)
1266		deliveries = append(
1267			deliveries,
1268			deliveriesFromLocalPeersWithMode(decision.digestPeers, envelope, store.NetworkSubscriptionModeDigest)...,
1269		)
1270		sort.SliceStable(deliveries, func(i int, j int) bool {
1271			return deliveries[i].PeerID < deliveries[j].PeerID
1272		})
1273		return deliveries, nil
1274	}
