1281	func (r *Router) selectEmptyThreadPeers(
1282		ctx context.Context,
1283		peers []LocalPeer,
1284		envelope Envelope,
1285		participants map[string]bool,
1286		mentioned map[string]bool,
1287	) (emptyThreadDeliveryDecision, error) {
1288		policy, coordinatorPeerID, err := r.channelFanoutPolicy(ctx, envelope)
1289		if err != nil {
1290			return emptyThreadDeliveryDecision{}, err
1291		}
1292		baseFull := r.participantMentionPeers(peers, envelope, participants, mentioned)
1293		switch policy {
1294		case store.NetworkFanoutPolicyAllMembers:
1295			full := append(cloneLocalPeers(baseFull.peers), r.allEligibleThreadPeers(peers, envelope, baseFull.seen)...)
1296			return emptyThreadDeliveryDecision{fullPeers: sortLocalPeers(full)}, nil
1297		case store.NetworkFanoutPolicyCoordinator:
1298			selected, ok := r.coordinatorPeer(peers, envelope, coordinatorPeerID, baseFull.seen)
1299			if ok {
1300				full := append(cloneLocalPeers(baseFull.peers), selected)
1301				return emptyThreadDeliveryDecision{fullPeers: sortLocalPeers(full)}, nil
1302			}
1303			return emptyThreadDeliveryDecision{
1304				fullPeers:   sortLocalPeers(baseFull.peers),
1305				digestPeers: r.threadDigestFallbackPeers(peers, envelope, baseFull.seen),
1306			}, nil
1307		default:
1308			full := r.selectCapabilityMatchedThreadPeers(peers, envelope, baseFull.peers, baseFull.seen)
1309			if len(full) > len(baseFull.peers) {
1310				return emptyThreadDeliveryDecision{fullPeers: sortLocalPeers(full)}, nil
1311			}
1312			return emptyThreadDeliveryDecision{
1313				fullPeers:   sortLocalPeers(baseFull.peers),
1314				digestPeers: r.threadDigestFallbackPeers(peers, envelope, baseFull.seen),
1315			}, nil
1316		}
1317	}
