1473	func rankActivationCandidates(peers []LocalPeer, envelope Envelope) []activationCandidate {
1474		candidates := make([]activationCandidate, 0, len(peers))
1475		terms := activationTerms(envelope)
1476		for _, peer := range peers {
1477			candidates = append(candidates, activationCandidate{
1478				peer:  peer,
1479				score: activationScore(peer, terms),
1480			})
1481		}
1482		sort.SliceStable(candidates, func(i int, j int) bool {
1483			if candidates[i].score != candidates[j].score {
1484				return candidates[i].score > candidates[j].score
1485			}
1486			return candidates[i].peer.PeerID < candidates[j].peer.PeerID
1487		})
1488		return candidates
1489	}
