1491	func activationTerms(envelope Envelope) []string {
1492		body, err := envelope.DecodeBody()
1493		if err != nil {
1494			return nil
1495		}
1496		var text string
1497		switch typed := body.(type) {
1498		case SayBody:
1499			text = typed.Text + " " + typed.Intent
1500		case CapabilityBody:
1501			text = typed.Capability.ID + " " + typed.Capability.Summary + " " + typed.Capability.Outcome
1502		default:
1503			return nil
1504		}
1505		fields := strings.FieldsFunc(strings.ToLower(text), func(r rune) bool {
1506			return (r < 'a' || r > 'z') && (r < '0' || r > '9')
1507		})
1508		terms := make([]string, 0, len(fields))
1509		seen := make(map[string]bool, len(fields))
1510		for _, field := range fields {
1511			if len(field) < 3 || seen[field] {
1512				continue
1513			}
1514			seen[field] = true
1515			terms = append(terms, field)
1516		}
1517		return terms
1518	}
