1520	func activationScore(peer LocalPeer, terms []string) int {
1521		if len(terms) == 0 {
1522			return 0
1523		}
1524		var builder strings.Builder
1525		builder.WriteString(strings.Join(peer.PeerCard.Capabilities, " "))
1526		for _, capability := range peer.CapabilityCatalog {
1527			builder.WriteByte(' ')
1528			builder.WriteString(capability.ID)
1529			builder.WriteByte(' ')
1530			builder.WriteString(capability.Summary)
1531			builder.WriteByte(' ')
1532			builder.WriteString(capability.Outcome)
1533		}
1534		haystack := strings.ToLower(builder.String())
1535		score := 0
1536		for _, term := range terms {
1537			if strings.Contains(haystack, term) {
1538				score++
1539			}
1540		}
1541		return score
1542	}
