459	func normalizeJoinChannelRequest(
460		ctx context.Context,
461		manager *Manager,
462		join sessionpkg.NetworkPeerJoin,
463	) (joinChannelRequest, error) {
464		if ctx == nil {
465			return joinChannelRequest{}, errors.New("network: join context is required")
466		}
467		if manager == nil {
468			return joinChannelRequest{}, errors.New("network: manager is required")
469		}
470		if err := ctx.Err(); err != nil {
471			return joinChannelRequest{}, err
472		}
473		if err := manager.lifecycleCtx.Err(); err != nil {
474			return joinChannelRequest{}, err
475		}
