484		}
485		if request.sessionID == "" {
486			return joinChannelRequest{}, fmt.Errorf("%w: session id is required", ErrMissingField)
487		}
488		if request.peerID == "" {
489			return joinChannelRequest{}, fmt.Errorf("%w: peer id is required", ErrMissingField)
490		}
491		if err := ValidateWorkspaceID(request.workspaceID); err != nil {
492			return joinChannelRequest{}, err
493		}
494		if err := ValidateChannel(request.channel); err != nil {
