509			if current.peerID == request.peerID &&
510				current.workspaceID == request.workspaceID &&
511				current.channel == request.channel {
512				return LocalPeer{}, true, nil
513			}
514			if err := m.LeaveChannel(ctx, request.sessionID); err != nil {
