552	func (m *Manager) newManagedSession(local LocalPeer) (*managedSession, error) {
553		if err := m.acquireBroadcastSubscription(local.WorkspaceID, local.Channel); err != nil {
554			m.router.Leave(local.SessionID)
555			return nil, err
556		}
557	
558		directSub, err := m.subscribeDirect(local.WorkspaceID, local.Channel, local.PeerID)
559		if err != nil {
560			return nil, m.rollbackManagedSessionJoin(local, nil, err)
561		}
562		heartbeat, err := m.startAuditedHeartbeat(local.SessionID, "")
563		if err != nil {
564			return nil, m.rollbackManagedSessionJoin(local, directSub, err)
565		}
566	
567		return &managedSession{
568			sessionID:   local.SessionID,
569			peerID:      local.PeerID,
570			workspaceID: local.WorkspaceID,
571			channel:     local.Channel,
572			directSub:   directSub,
573			heartbeat:   heartbeat,
574		}, nil
575	}
