577	func (m *Manager) rollbackManagedSessionJoin(
578		local LocalPeer,
579		directSub *nats.Subscription,
580		joinErr error,
581	) error {
582		if directSub != nil {
583			if unsubscribeErr := cleanupSubscription(
584				directSub.Unsubscribe,
585				"network: unsubscribe direct subject for %q: %w",
586				local.SessionID,
587			); unsubscribeErr != nil {
588				joinErr = errors.Join(joinErr, unsubscribeErr)
589			}
590		}
591		if releaseErr := m.releaseBroadcastSubscription(local.WorkspaceID, local.Channel); releaseErr != nil {
592			joinErr = errors.Join(joinErr, releaseErr)
593		}
594		m.router.Leave(local.SessionID)
595		return joinErr
596	}
