604	// LeaveChannel removes one daemon-local session from the active network runtime.
605	func (m *Manager) LeaveChannel(ctx context.Context, sessionID string) error {
606		if ctx == nil {
607			return errors.New("network: leave context is required")
608		}
609		if m == nil {
610			return errors.New("network: manager is required")
611		}
612		if err := ctx.Err(); err != nil {
613			return err
614		}
615	
616		targetSession := strings.TrimSpace(sessionID)
617		if targetSession == "" {
618			return fmt.Errorf("%w: session id is required", ErrMissingField)
619		}
620	
621		runtime, ok := m.removeSessionRuntime(targetSession)
622		if !ok {
623			m.deliveries.dropSession(targetSession)
624			m.dispatchLocalPeerLeft(ctx, targetSession)
625			return nil
626		}
627	
628		var errs []error
629		m.deliveries.dropSession(targetSession)
630	
631		if runtime.heartbeat != nil {
632			runtime.heartbeat.Stop()
633		}
634		if runtime.directSub != nil {
635			if err := runtime.directSub.Unsubscribe(); err != nil && !errors.Is(err, nats.ErrConnectionClosed) {
636				errs = append(errs, fmt.Errorf("network: unsubscribe direct subject for %q: %w", targetSession, err))
637			}
638		}
639		if err := m.releaseBroadcastSubscription(runtime.workspaceID, runtime.channel); err != nil {
640			errs = append(errs, err)
641		}
642		m.dispatchLocalPeerLeft(ctx, targetSession)
643	
644		m.logger.Info(
645			"network.peer.left",
646			"session_id", runtime.sessionID,
647			"peer_id", runtime.peerID,
648			"workspace_id", runtime.workspaceID,
649			managerChannelKey, runtime.channel,
650		)
651		return errors.Join(errs...)
652	}
