678	// Send publishes one outbound envelope through the owned router/transport.
679	func (m *Manager) Send(ctx context.Context, req SendRequest) (string, error) {
680		if ctx == nil {
681			return "", errors.New("network: send context is required")
682		}
683		if m == nil || m.router == nil {
684			return "", errors.New("network: manager router is required")
685		}
686		m.sweepExpiredRemotePeers(ctx, m.now())
687	
688		prepared, err := m.router.PrepareSend(ctx, req)
689		if err != nil {
690			return "", err
691		}
692		writeResult, wrote, err := m.writeConversationMessage(ctx, req.SessionID, AuditDirectionSent, prepared.Envelope)
693		if err != nil {
694			m.recordAuditRejected(ctx, req.SessionID, prepared.Envelope, conversationPersistenceReason(err))
695			return "", err
696		}
697		if wrote && writeResult.Duplicate {
698			m.logger.Info(
699				"network.message.send_duplicate",
700				networkLogFields(prepared.Envelope, "session_id", req.SessionID)...)
701			return prepared.ID, nil
702		}
703	
704		result, err := m.router.PublishPrepared(ctx, prepared)
705		if err != nil {
706			m.recordAuditRejected(ctx, req.SessionID, prepared.Envelope, "publish_failed")
707			return "", err
708		}
709		m.recordSentDelivery(ctx, req.SessionID, result.Envelope, wrote)
710		return result.ID, nil
711	}
