753	func (m *Manager) prepareRuntimeSend(req RuntimeSendRequest) (SendResult, error) {
754		if m == nil || m.router == nil {
755			return SendResult{}, errors.New("network: manager router is required")
756		}
757		now := m.now().UTC()
758		workspaceID := strings.TrimSpace(req.WorkspaceID)
759		if err := ValidateWorkspaceID(workspaceID); err != nil {
760			return SendResult{}, err
761		}
762		channel := strings.TrimSpace(req.Channel)
763		if err := ValidateChannel(channel); err != nil {
764			return SendResult{}, err
765		}
766		id := normalizeOptionalIdentifier(req.ID)
767		if id == nil {
768			id = ptrString(store.NewID("msg"))
769		}
770		envelope := Envelope{
771			Protocol:    ProtocolV0,
772			ID:          *id,
773			WorkspaceID: workspaceID,
774			Kind:        Kind(strings.TrimSpace(string(req.Kind))),
775			Channel:     channel,
776			Surface:     normalizeOptionalSurface(req.Surface),
777			ThreadID:    normalizeOptionalIdentifier(req.ThreadID),
778			DirectID:    normalizeOptionalIdentifier(req.DirectID),
779			From:        RuntimePeerID,
780			To:          normalizeOptionalIdentifier(req.To),
781			Mentions:    normalizeEnvelopeMentions(req.Mentions),
782			WorkID:      normalizeOptionalIdentifier(req.WorkID),
783			ReplyTo:     normalizeOptionalIdentifier(req.ReplyTo),
784			TraceID:     normalizeOptionalIdentifier(req.TraceID),
785			CausationID: normalizeOptionalIdentifier(req.CausationID),
786			TS:          now.Unix(),
787			ExpiresAt:   cloneInt64Ptr(req.ExpiresAt),
788			Body:        cloneRawMessage(req.Body),
789			Ext:         cloneExtensionMap(req.Ext),
790		}
791		if isConversationKind(envelope.Kind) &&
792			envelope.Surface != nil &&
793			*envelope.Surface == SurfaceDirect &&
794			envelope.To != nil {
795			directID, _, _, err := DirectRoomIdentity(envelope.WorkspaceID, channel, envelope.From, *envelope.To)
796			if err != nil {
797				return SendResult{}, err
798			}
799			envelope.DirectID = ptrString(directID)
800		}
801		if envelope.IsDirected() && !m.peers.HasPresence(envelope.WorkspaceID, envelope.Channel, *envelope.To, now) {
802			return SendResult{}, fmt.Errorf(
803				"%w: peer_id=%q channel=%q",
804				ErrTargetPeerNotFound,
805				*envelope.To,
806				envelope.Channel,
807			)
808		}
809		if err := ValidateEnvelope(envelope, ValidateOptions{Now: now, MaxReplayAge: m.router.maxReplayAge}); err != nil {
810			return SendResult{}, err
811		}
812		subject, err := subjectForEnvelope(envelope)
813		if err != nil {
814			return SendResult{}, err
815		}
816		return SendResult{ID: envelope.ID, Subject: subject, Envelope: envelope}, nil
817	}
