819	func (m *Manager) startAuditedHeartbeat(sessionID string, summary string) (*Heartbeat, error) {
820		if m == nil || m.router == nil || m.peers == nil {
821			return nil, errors.New("network: manager heartbeat dependencies are required")
822		}
823	
824		interval := m.peers.GreetInterval()
825		if interval <= 0 {
826			return nil, fmt.Errorf("%w: greet interval must be positive", ErrInvalidField)
827		}
828		if err := m.publishGreetWithAudit(m.lifecycleCtx, sessionID, summary); err != nil {
829			return nil, err
830		}
831	
832		heartbeat := &Heartbeat{
833			stop: make(chan struct{}),
834			done: make(chan struct{}),
835		}
836	
837		go func() {
838			defer close(heartbeat.done)
839	
840			ticker := time.NewTicker(interval)
841			defer ticker.Stop()
842	
843			for {
844				select {
845				case <-heartbeat.stop:
846					return
847				case <-m.lifecycleCtx.Done():
848					return
849				case <-ticker.C:
850					m.sweepExpiredRemotePeers(m.lifecycleCtx, m.now())
851					if err := m.publishGreetWithAudit(m.lifecycleCtx, sessionID, summary); err != nil {
852						switch {
853						case errors.Is(err, context.Canceled), errors.Is(err, ErrLocalPeerNotFound):
854							return
855						default:
856							m.logger.Warn("network.peer.heartbeat_failed", "session_id", sessionID, "error", err)
857						}
858					}
859				}
860			}
861		}()
862	
863		return heartbeat, nil
864	}
865	
866	func (m *Manager) publishGreetWithAudit(ctx context.Context, sessionID string, summary string) error {
867		if m == nil || m.router == nil {
868			return errors.New("network: manager router is required")
869		}
870	
871		result, err := m.router.PublishGreet(ctx, sessionID, summary)
872		if err != nil {
873			return err
874		}
875		if _, _, err := m.writeConversationMessage(ctx, sessionID, AuditDirectionSent, result.Envelope); err != nil {
876			return fmt.Errorf("network: persist greet presence: %w", err)
877		}
878		m.recordAuditSent(ctx, sessionID, result.Envelope)
879		return nil
880	}
