933	func (m *Manager) Status(ctx context.Context) (*Status, error) {
934		if ctx == nil {
935			return nil, errors.New("network: status context is required")
936		}
937		if m == nil {
938			return nil, errors.New("network: manager is required")
939		}
940		if err := ctx.Err(); err != nil {
941			return nil, err
942		}
943	
944		peers, err := m.ListPeers(ctx, "", "")
945		if err != nil {
946			return nil, err
947		}
948		channels, err := m.ListChannels(ctx, "")
949		if err != nil {
950			return nil, err
951		}
952		localPeers := 0
953		for _, peer := range peers {
954			if peer.Local {
955				localPeers++
956			}
957		}
958		host, port := transportListener(m.transport)
959		status := StatusRunning
960		connected, lastDisconnect := m.connectionState()
961		if !connected {
962			status = StatusDisconnected
963		}
964		deliveryStats := m.deliveries.stats()
965		stats := m.stats.snapshot()
966		metricSamples := append([]MetricSample(nil), stats.Metrics...)
967		metricSamples = append(metricSamples, m.deliveries.queueDepthMetrics()...)
968		sortMetricSamples(metricSamples)
969	
970		return &Status{
971			Enabled:              true,
972			Status:               status,
973			ListenerHost:         host,
974			ListenerPort:         port,
975			LocalPeers:           localPeers,
976			RemotePeers:          len(peers) - localPeers,
977			Channels:             len(channels),
978			QueuedMessages:       deliveryStats.QueuedMessages,
979			QueuedSessions:       deliveryStats.QueuedSessions,
980			DeliveryWorkers:      deliveryStats.DeliveryWorkers,
981			DeliveryQueueDepth:   deliveryStats.QueuedMessages,
982			MessagesSent:         stats.MessagesSent,
983			MessagesReceived:     stats.MessagesReceived,
984			MessagesRejected:     stats.MessagesRejected,
985			MessagesDelivered:    stats.MessagesDelivered,
986			WorkflowTaggedEvents: stats.WorkflowTaggedEvents,
987			HandoffTaggedEvents:  stats.HandoffTaggedEvents,
988			OpenThreads:          stats.OpenThreads,
989			OpenDirectRooms:      stats.OpenDirectRooms,
990			OpenWorkItems:        stats.OpenWorkItems,
991			ConversationMessages: stats.ConversationMessages,
992			WorkTransitions:      stats.WorkTransitions,
993			DirectResolves:       stats.DirectResolves,
994			LastDisconnect:       lastDisconnect,
995			KindMetrics:          stats.KindMetrics,
996			Metrics:              metricSamples,
997		}, nil
998	}
