1029	// Shutdown drains all background work and stops the owned transport.
1030	func (m *Manager) Shutdown(ctx context.Context) error {
1031		if ctx == nil {
1032			return errors.New("network: shutdown context is required")
1033		}
1034		if m == nil {
1035			return nil
1036		}
1037	
1038		m.mu.Lock()
1039		if m.closed {
1040			m.mu.Unlock()
1041			return nil
1042		}
1043		m.closed = true
1044	
1045		sessions := make([]*managedSession, 0, len(m.sessions))
1046		for _, runtime := range m.sessions {
1047			sessions = append(sessions, runtime)
1048		}
1049		channels := make([]*managedChannel, 0, len(m.channels))
1050		for _, runtime := range m.channels {
1051			channels = append(channels, runtime)
1052		}
1053		m.sessions = make(map[string]*managedSession)
1054		m.channels = make(map[string]*managedChannel)
1055		m.mu.Unlock()
1056	
1057		deliveryStats := m.deliveries.stats()
1058		m.cancel()
1059	
1060		var errs []error
1061		for _, runtime := range sessions {
1062			if runtime == nil {
1063				continue
1064			}
1065			m.deliveries.dropSession(runtime.sessionID)
1066			if runtime.heartbeat != nil {
1067				runtime.heartbeat.Stop()
1068			}
1069			if runtime.directSub != nil {
1070				if err := runtime.directSub.Unsubscribe(); err != nil && !errors.Is(err, nats.ErrConnectionClosed) {
1071					errs = append(
1072						errs,
1073						fmt.Errorf("network: unsubscribe direct subject for %q: %w", runtime.sessionID, err),
1074					)
1075				}
1076			}
1077			m.router.Leave(runtime.sessionID)
1078		}
1079		for _, runtime := range channels {
1080			if runtime == nil || runtime.broadcastSub == nil {
1081				continue
1082			}
1083			if err := runtime.broadcastSub.Unsubscribe(); err != nil && !errors.Is(err, nats.ErrConnectionClosed) {
1084				errs = append(errs, fmt.Errorf("network: unsubscribe broadcast subject for %q: %w", runtime.channel, err))
1085			}
1086		}
1087	
1088		m.deliveries.wait()
1089		if m.transport != nil {
1090			if err := m.transport.Shutdown(ctx); err != nil {
1091				errs = append(errs, err)
1092			}
1093		}
1094		m.logger.Info(
1095			"network.stopped",
1096			"pending_messages", deliveryStats.QueuedMessages+deliveryStats.InFlightMessages,
1097			"queued_messages", deliveryStats.QueuedMessages,
1098			"inflight_messages", deliveryStats.InFlightMessages,
1099			"delivery_workers", deliveryStats.DeliveryWorkers,
1100		)
1101	
1102		return errors.Join(errs...)
1103	}
