1105	func (m *Manager) handleInboundMessage(payload []byte) {
1106		if m == nil || m.router == nil {
1107			return
1108		}
1109		if err := m.lifecycleCtx.Err(); err != nil {
1110			return
1111		}
1112	
1113		result, err := m.router.Receive(m.lifecycleCtx, payload)
1114		if err != nil {
1115			m.logger.Warn("network.message.receive_failed", "error", err)
1116			return
1117		}
1118		m.dispatchNetworkPeerLifecycleHooks(m.lifecycleCtx, result.PeerEvents)
1119		persisted, err := m.writeInboundConversationMessages(m.lifecycleCtx, result)
1120		if err != nil {
1121			m.logger.Warn("network.message.persist_failed", "error", err)
1122			if result.Envelope != nil {
1123				m.recordAuditRejected(
1124					m.lifecycleCtx,
1125					inboundRejectedSessionID(m, *result.Envelope),
1126					*result.Envelope,
1127					conversationPersistenceReason(err),
1128				)
1129			}
1130			return
1131		}
1132		if persisted.Duplicate {
1133			m.logger.Info("network.message.receive_duplicate_store", "message_id", persisted.MessageID)
1134			return
1135		}
1136		m.recordInboundAudit(result, persisted.MessageIDs)
1137	
1138		if len(result.Deliveries) == 0 {
1139			return
1140		}
1141		deliveries, err := m.applyDeliverySubscriptions(m.lifecycleCtx, result.Deliveries)
1142		if err != nil {
1143			m.logger.Warn("network.message.subscription_filter_failed", "error", err)
1144			return
1145		}
1146		if len(deliveries) == 0 {
1147			return
1148		}
1149		if err := m.deliveries.accept(m.lifecycleCtx, deliveries); err != nil {
1150			m.logger.Warn("network.message.accept_failed", "error", err)
1151		}
1152	}
