1154	func (m *Manager) applyDeliverySubscriptions(ctx context.Context, deliveries []Delivery) ([]Delivery, error) {
1155		if len(deliveries) == 0 {
1156			return nil, nil
1157		}
1158		subscriptions := networkSubscriptionStoreFromCandidate(m.conversations)
1159		filtered := make([]Delivery, 0, len(deliveries))
1160		for _, delivery := range deliveries {
1161			next := delivery
1162			next.Mode = normalizedDeliverySubscriptionMode(delivery.Mode)
1163			if subscriptions != nil {
1164				mode, err := deliverySubscriptionMode(ctx, subscriptions, delivery)
1165				if err != nil {
1166					return nil, err
1167				}
1168				if mode == store.NetworkSubscriptionModeMute {
1169					continue
1170				}
1171				next.Mode = mode
1172			}
1173			filtered = append(filtered, next)
1174		}
1175		return filtered, nil
1176	}
