1178	func networkSubscriptionStoreFromCandidate(candidate any) networkSubscriptionStore {
1179		subscriptions, ok := candidate.(networkSubscriptionStore)
1180		if !ok {
1181			return nil
1182		}
1183		return subscriptions
1184	}
