1186	func deliverySubscriptionMode(
1187		ctx context.Context,
1188		subscriptions networkSubscriptionStore,
1189		delivery Delivery,
1190	) (string, error) {
1191		if subscriptions == nil {
1192			return store.NetworkSubscriptionModeFull, nil
1193		}
1194		if deliveryMentionsPeer(delivery.Envelope, delivery.PeerID) || deliveryAddressedToPeer(delivery) {
1195			return store.NetworkSubscriptionModeFull, nil
1196		}
1197		workspaceID := strings.TrimSpace(delivery.Envelope.WorkspaceID)
1198		channel := strings.TrimSpace(delivery.Envelope.Channel)
1199		peerID := strings.TrimSpace(delivery.PeerID)
1200		if workspaceID == "" || channel == "" || peerID == "" {
1201			return store.NetworkSubscriptionModeFull, nil
1202		}
1203		if delivery.Envelope.ThreadID != nil {
1204			threadID := strings.TrimSpace(*delivery.Envelope.ThreadID)
1205			if threadID != "" {
1206				threadEntry, ok, err := firstApplicableSubscription(
1207					ctx,
1208					subscriptions,
1209					store.NetworkSubscriptionQuery{
1210						WorkspaceID: workspaceID,
1211						Channel:     channel,
1212						ThreadID:    threadID,
1213						PeerID:      peerID,
1214						Limit:       10,
1215					},
1216					threadID,
1217					delivery.Envelope,
1218				)
1219				if err != nil {
1220					return "", err
1221				}
1222				if ok {
1223					return normalizedDeliverySubscriptionMode(threadEntry.Mode), nil
1224				}
1225			}
1226		}
1227		channelEntry, ok, err := firstApplicableSubscription(
1228			ctx,
1229			subscriptions,
1230			store.NetworkSubscriptionQuery{
1231				WorkspaceID: workspaceID,
1232				Channel:     channel,
1233				PeerID:      peerID,
1234				Limit:       50,
1235			},
1236			"",
1237			delivery.Envelope,
1238		)
1239		if err != nil {
1240			return "", err
1241		}
1242		if ok {
1243			return normalizedDeliverySubscriptionMode(channelEntry.Mode), nil
1244		}
1245		return normalizedDeliverySubscriptionMode(delivery.Mode), nil
1246	}
1247	
1248	func firstApplicableSubscription(
1249		ctx context.Context,
1250		subscriptions networkSubscriptionStore,
1251		query store.NetworkSubscriptionQuery,
1252		threadID string,
1253		envelope Envelope,
1254	) (store.NetworkSubscriptionEntry, bool, error) {
1255		entries, err := subscriptions.ListNetworkSubscriptions(ctx, query)
1256		if err != nil {
1257			return store.NetworkSubscriptionEntry{}, false, fmt.Errorf("network: list delivery subscriptions: %w", err)
1258		}
1259		for _, entry := range entries {
1260			if strings.TrimSpace(entry.ThreadID) != strings.TrimSpace(threadID) {
1261				continue
1262			}
1263			if !subscriptionKeywordFiltersMatch(entry.KeywordFilters, envelope) {
1264				continue
1265			}
1266			return entry, true, nil
1267		}
1268		return store.NetworkSubscriptionEntry{}, false, nil
1269	}
1270	
1271	func subscriptionKeywordFiltersMatch(filters []string, envelope Envelope) bool {
1272		normalizedFilters := normalizeSubscriptionKeywordFilters(filters)
1273		if len(normalizedFilters) == 0 {
1274			return true
1275		}
1276		text := strings.ToLower(deliverySubscriptionSearchText(envelope))
1277		if text == "" {
1278			return false
1279		}
1280		for _, filter := range normalizedFilters {
1281			if strings.Contains(text, strings.ToLower(filter)) {
1282				return true
1283			}
1284		}
1285		return false
1286	}
1287	
1288	func normalizeSubscriptionKeywordFilters(filters []string) []string {
1289		normalized := make([]string, 0, len(filters))
1290		seen := make(map[string]struct{}, len(filters))
1291		for _, filter := range filters {
1292			trimmed := strings.TrimSpace(filter)
1293			if trimmed == "" {
1294				continue
1295			}
1296			key := strings.ToLower(trimmed)
1297			if _, ok := seen[key]; ok {
1298				continue
1299			}
1300			seen[key] = struct{}{}
1301			normalized = append(normalized, trimmed)
1302		}
1303		return normalized
1304	}
1305	
1306	func deliverySubscriptionSearchText(envelope Envelope) string {
1307		body, err := envelope.DecodeBody()
1308		if err != nil {
1309			return strings.TrimSpace(string(envelope.Body))
1310		}
1311		return previewForBody(body)
1312	}
1313	
1314	func deliveryMentionsPeer(envelope Envelope, peerID string) bool {
1315		target := strings.TrimSpace(peerID)
1316		if target == "" {
1317			return false
1318		}
1319		return slices.Contains(normalizeEnvelopeMentions(envelope.Mentions), target)
1320	}
1321	
1322	func deliveryAddressedToPeer(delivery Delivery) bool {
1323		if delivery.Envelope.To == nil {
1324			return false
1325		}
1326		return strings.TrimSpace(*delivery.Envelope.To) != "" &&
1327			strings.TrimSpace(*delivery.Envelope.To) == strings.TrimSpace(delivery.PeerID)
1328	}
1329	
1330	func normalizedDeliverySubscriptionMode(mode string) string {
1331		switch strings.TrimSpace(mode) {
1332		case store.NetworkSubscriptionModeMute:
1333			return store.NetworkSubscriptionModeMute
1334		case store.NetworkSubscriptionModeDigest:
1335			return store.NetworkSubscriptionModeDigest
1336		default:
1337			return store.NetworkSubscriptionModeFull
1338		}
1339	}
