1341	type conversationPersistenceSummary struct {
1342		MessageIDs map[string]struct{}
1343		Duplicate  bool
1344		MessageID  string
1345	}
1346	
1347	func (m *Manager) writeInboundConversationMessages(
1348		ctx context.Context,
1349		result RouteResult,
1350	) (conversationPersistenceSummary, error) {
1351		summary := conversationPersistenceSummary{MessageIDs: make(map[string]struct{})}
1352		if m == nil || m.conversations == nil {
1353			return summary, nil
1354		}
1355		if result.Envelope != nil && !result.Rejected && !result.Ignored && len(result.Deliveries) > 0 {
1356			writeResult, wrote, err := m.writeConversationMessage(
1357				ctx,
1358				result.Deliveries[0].SessionID,
1359				AuditDirectionReceived,
1360				*result.Envelope,
1361			)
1362			if err != nil {
1363				return conversationPersistenceSummary{}, err
1364			}
1365			if wrote {
1366				if writeResult.Duplicate {
1367					if m.isLocalEnvelopeSender(*result.Envelope) {
1368						summary.MessageIDs[result.Envelope.ID] = struct{}{}
1369						return summary, nil
1370					}
1371					summary.Duplicate = true
1372					summary.MessageID = writeResult.MessageID
1373					return summary, nil
1374				}
1375				summary.MessageIDs[result.Envelope.ID] = struct{}{}
1376			}
1377		}
1378	
1379		for _, envelope := range result.Generated {
1380			local, ok := m.peers.LocalByPeer(envelope.WorkspaceID, envelope.Channel, envelope.From)
1381			if !ok {
1382				continue
1383			}
1384			writeResult, wrote, err := m.writeConversationMessage(ctx, local.SessionID, AuditDirectionSent, envelope)
1385			if err != nil {
1386				return conversationPersistenceSummary{}, err
1387			}
1388			if wrote && !writeResult.Duplicate {
1389				summary.MessageIDs[envelope.ID] = struct{}{}
1390			}
1391		}
1392		return summary, nil
1393	}
