1403	func (m *Manager) writeConversationMessage(
1404		ctx context.Context,
1405		sessionID string,
1406		direction string,
1407		envelope Envelope,
1408	) (store.NetworkConversationWriteResult, bool, error) {
1409		if ctx == nil {
1410			return store.NetworkConversationWriteResult{}, false, errors.New("network: conversation context is required")
1411		}
1412		if m == nil || m.conversations == nil || !isTimelineKind(envelope.Kind) {
1413			return store.NetworkConversationWriteResult{}, false, nil
1414		}
1415		entry, ok, err := normalizeTimelineMessageEntry(sessionID, direction, envelope, envelopeRecordTime(envelope, m.now))
1416		if err != nil {
1417			return store.NetworkConversationWriteResult{}, false, err
1418		}
1419		if !ok {
1420			return store.NetworkConversationWriteResult{}, false, nil
1421		}
1422		result, err := m.conversations.WriteConversationMessage(ctx, entry)
1423		if err != nil {
1424			return store.NetworkConversationWriteResult{}, true, err
1425		}
1426		if !result.Duplicate {
1427			m.observeConversationWrite(ctx, entry, result)
1428		}
1429		return result, true, nil
1430	}
