1432	func isTimelineKind(kind Kind) bool {
1433		switch kind {
1434		case KindGreet, KindWhois, KindSay, KindCapability, KindReceipt, KindTrace:
1435			return true
1436		default:
1437			return false
1438		}
1439	}
