1441	func envelopeRecordTime(envelope Envelope, now func() time.Time) time.Time {
1442		if envelope.TS > 0 {
1443			return time.Unix(envelope.TS, 0).UTC()
1444		}
1445		if now != nil {
1446			return now().UTC()
1447		}
1448		return time.Now().UTC()
1449	}
