1462	func (m *Manager) recordInboundAudit(result RouteResult, persisted map[string]struct{}) {
1463		if m == nil {
1464			return
1465		}
1466		recordedReceivers := make(map[string]struct{})
1467		if result.Envelope != nil && result.Rejected {
1468			sessionID := ""
1469			if result.Envelope.IsDirected() {
1470				if target, ok := m.peers.LocalByPeer(
1471					result.Envelope.WorkspaceID,
1472					result.Envelope.Channel,
1473					*result.Envelope.To,
1474				); ok {
1475					sessionID = target.SessionID
1476				}
1477			}
1478			reason := ""
1479			if result.ReasonCode != nil {
1480				reason = strings.TrimSpace(string(*result.ReasonCode))
1481			}
1482			m.recordAuditRejected(m.lifecycleCtx, sessionID, *result.Envelope, reason)
1483		}
1484	
1485		for _, delivery := range result.Deliveries {
1486			_, durable := persisted[delivery.Envelope.ID]
1487			m.recordReceivedDelivery(m.lifecycleCtx, delivery.SessionID, delivery.Envelope, durable)
1488			recordedReceivers[delivery.SessionID] = struct{}{}
1489		}
1490		for _, sessionID := range m.controlMessageReceivers(result) {
1491			if _, ok := recordedReceivers[sessionID]; ok {
1492				continue
1493			}
1494			_, durable := persisted[result.Envelope.ID]
1495			m.recordReceivedDelivery(m.lifecycleCtx, sessionID, *result.Envelope, durable)
1496		}
1497		for _, envelope := range result.Generated {
1498			local, ok := m.peers.LocalByPeer(envelope.WorkspaceID, envelope.Channel, envelope.From)
1499			if !ok {
1500				continue
1501			}
1502			_, durable := persisted[envelope.ID]
1503			m.recordSentDelivery(m.lifecycleCtx, local.SessionID, envelope, durable)
1504		}
1505	}
