1545	func conversationPersistenceReason(err error) string {
1546		switch {
1547		case err == nil:
1548			return ""
1549		case errors.Is(err, store.ErrNetworkWorkClosed):
1550			return "work_closed"
1551		case errors.Is(err, store.ErrNetworkWorkContainerMismatch):
