597					SessionID:                 target,
598					ReplyGuidanceDelivered:    state.replyDelivered,
599					ProtocolGuidanceDelivered: state.protocolDelivered,
600				},
601			); err != nil && c.logger != nil {
602				c.logger.Warn(
603					"network.delivery_guidance.persist_failed",
604					"session_id",
605					target,
606					"error",
607					err,
608				)
609			}
