613	func (c *deliveryCoordinator) trigger(sessionID string) {
614		if c == nil {
615			return
616		}
617		if err := c.lifecycleCtx.Err(); err != nil {
618			return
619		}
620		if c.queueDepth(sessionID) == 0 {
621			return
622		}
623	
624		state := &deliveryState{done: make(chan struct{})}
625		if _, loaded := c.deliveries.LoadOrStore(sessionID, state); loaded {
626			return
627		}
628	
629		c.wg.Add(1)
630		go c.runWorker(sessionID, state)
631	}
