633	func (c *deliveryCoordinator) runWorker(sessionID string, state *deliveryState) {
634		defer c.wg.Done()
635		defer close(state.done)
636		defer c.deliveries.Delete(sessionID)
637	
638		target := strings.TrimSpace(sessionID)
639		for {
640			if err := c.lifecycleCtx.Err(); err != nil {
641				return
642			}
643			if c.prompter.IsPrompting(target) {
644				return
645			}
646	
647			item, ok := c.dequeue(target)
648			if !ok {
649				return
650			}
651			if !c.processQueuedItem(target, item, state) {
652				return
653			}
654		}
655	}
