657	func (c *deliveryCoordinator) processQueuedItem(sessionID string, item queuedEnvelope, state *deliveryState) bool {
658		c.markInFlight(sessionID, item)
659		batch := c.collectDigestBatch(sessionID, item)
660		envelope := batch[0].Envelope
661	
662		message, err := c.formatQueuedDeliveryBatch(sessionID, batch)
663		if err != nil {
664			c.handleRenderFailure(sessionID, batch, state, err)
665			return false
666		}
667	
668		cost := deliveredPromptCostForMessage(message)
669		events, err := c.prompter.PromptNetwork(
670			c.lifecycleCtx,
671			sessionID,
672			message,
673			promptNetworkMeta(envelope, cost, batch[0].PromptMode),
674		)
675		if err != nil {
676			c.handleDeliveryFailure(sessionID, batch, state, err)
677			return false
678		}
679		if !c.drainPromptEvents(events) {
680			c.handleInterruptedDelivery(sessionID, batch)
681			return false
682		}
683	
684		c.finishDeliveredMessages(sessionID, batch, cost)
685		return true
686	}
