688	func (c *deliveryCoordinator) collectDigestBatch(sessionID string, first queuedEnvelope) []queuedEnvelope {
689		if normalizePromptDeliveryMode(first.PromptMode) != store.NetworkSubscriptionModeDigest ||
690			c.digestMaxEnvelopes <= 1 {
691			return []queuedEnvelope{first}
692		}
693		if c.digestFlushInterval > 0 {
694			timer := time.NewTimer(c.digestFlushInterval)
695			defer timer.Stop()
696			select {
697			case <-timer.C:
698			case <-c.lifecycleCtx.Done():
699				return []queuedEnvelope{first}
700			}
701		}
702	
703		batch := []queuedEnvelope{first}
704		batch = append(batch, c.dequeueDigestBatch(sessionID, first, c.digestMaxEnvelopes-1)...)
705		return batch
706	}
