708	func (c *deliveryCoordinator) formatQueuedDeliveryBatch(
709		sessionID string,
710		batch []queuedEnvelope,
711	) (string, error) {
712		if len(batch) == 0 {
713			return "", errors.New("network: delivery batch is empty")
714		}
715		guidanceMode := c.guidanceModeForDelivery(sessionID, batch[0].Envelope)
716		if len(batch) == 1 || normalizePromptDeliveryMode(batch[0].PromptMode) != store.NetworkSubscriptionModeDigest {
717			return c.formatNetworkMessageWithDeliveryMode(batch[0].Envelope, guidanceMode, batch[0].PromptMode)
718		}
719		envelopes := make([]Envelope, 0, len(batch))
720		for _, item := range batch {
721			envelopes = append(envelopes, item.Envelope)
722		}
723		return formatNetworkDigestBatchMessage(envelopes, guidanceMode)
724	}
