780	func (c *deliveryCoordinator) handleRenderFailure(
781		sessionID string,
782		items []queuedEnvelope,
783		state *deliveryState,
784		err error,
785	) {
786		c.clearInFlight(sessionID)
787		retryItems := nextRetryBatch(items)
788		requeued := c.requeueFrontBatch(sessionID, retryItems)
789		item := firstQueuedBatchItem(retryItems)
790		c.logger.Warn(
791			"network.message.render_failed",
792			"session_id", sessionID,
793			"envelope_id", item.Envelope.ID,
794			"error", err,
795			"retry_attempt", item.RetryAttempt,
796		)
797		if requeued && json.Valid(item.Envelope.Body) {
798			c.retryAfterWorkerExit(sessionID, item, state)
799		}
800	}
