838	func (c *deliveryCoordinator) finishDeliveredMessages(
839		sessionID string,
840		items []queuedEnvelope,
841		cost deliveredPromptCost,
842	) {
843		c.clearInFlight(sessionID)
844		if len(items) == 0 {
845			return
846		}
847		for _, item := range items {
848			c.markGuidanceDelivered(sessionID, item)
849		}
850	
851		item := items[0]
852		latency := max(c.now().Sub(item.AcceptedAt), 0)
853	
854		c.logger.Info(
855			"network.message.delivered",
856			"session_id", sessionID,
857			"message_id", item.Envelope.ID,
858			"batch_size", len(items),
859			"kind", string(item.Envelope.Kind),
860			"channel", item.Envelope.Channel,
861			"delivery_mode", item.DeliveryMode,
862			"prompt_size_bytes", cost.PromptSizeBytes,
863			"estimated_prompt_tokens", cost.EstimatedPromptTokens,
864			"latency_ms", latency.Milliseconds(),
865		)
866		if c.onDelivered != nil {
867			allocations := deliveredPromptCostAllocations(items, cost)
868			for idx, deliveredItem := range items {
869				itemLatency := max(c.now().Sub(deliveredItem.AcceptedAt), 0)
870				c.onDelivered(
871					sessionID,
872					deliveredItem.PeerID,
873					deliveredItem.Envelope,
874					deliveredItem.DeliveryMode,
875					itemLatency,
876					allocations[idx],
877				)
878			}
879		}
880	}
