940	func (c *deliveryCoordinator) retryAfterWorkerExit(sessionID string, item queuedEnvelope, state *deliveryState) {
941		if c == nil || state == nil {
942			return
943		}
944	
945		target := strings.TrimSpace(sessionID)
946		if target == "" {
947			return
948		}
949	
950		delay := c.retryDelayFor(item.RetryAttempt)
951		c.wg.Go(func() {
952			select {
953			case <-state.done:
954			case <-c.lifecycleCtx.Done():
955				return
956			}
957	
958			c.scheduleRetry(c.lifecycleCtx, delay, func() {
959				if err := c.lifecycleCtx.Err(); err != nil {
960					return
961				}
962				if c.prompter.IsPrompting(target) {
963					return
964				}
965				if c.queueDepth(target) == 0 {
966					return
967				}
968				c.trigger(target)
969			})
970		})
971	}
