973	func (c *deliveryCoordinator) retryDelayFor(attempt int) time.Duration {
974		if c == nil {
975			return defaultDeliveryRetryBaseDelay
976		}
977		delay := c.retryBaseDelay
978		for i := 1; i < attempt; i++ {
979			if delay >= c.retryMaxDelay/2 {
980				return c.retryMaxDelay
981			}
982			delay *= 2
983		}
984		if delay > c.retryMaxDelay {
985			return c.retryMaxDelay
986		}
987		return delay
988	}
989	
990	func scheduleDeliveryRetry(ctx context.Context, delay time.Duration, fn func()) {
991		if fn == nil {
992			return
993		}
994		if delay <= 0 {
995			select {
996			case <-ctx.Done():
997				return
998			default:
999				fn()
1000				return
1001			}
1002		}
1003	
1004		timer := time.NewTimer(delay)
1005		defer timer.Stop()
1006	
1007		select {
1008		case <-ctx.Done():
1009			return
1010		case <-timer.C:
1011			fn()
1012		}
1013	}
