1015	func (c *deliveryCoordinator) stats() deliveryCoordinatorStats {
1016		if c == nil {
1017			return deliveryCoordinatorStats{}
1018		}
1019	
1020		c.mu.Lock()
1021		queues := make([]*inboundQueue, 0, len(c.queues))
1022		for _, queue := range c.queues {
1023			queues = append(queues, queue)
1024		}
1025		inFlightMessages := len(c.inFlight)
1026		c.mu.Unlock()
1027	
1028		stats := deliveryCoordinatorStats{
1029			InFlightMessages: inFlightMessages,
1030		}
1031		for _, queue := range queues {
