1033			if depth <= 0 {
1034				continue
1035			}
1036			stats.QueuedMessages += depth
1037			stats.QueuedSessions++
1038		}
1039		c.deliveries.Range(func(_, _ any) bool {
1040			stats.DeliveryWorkers++
1041			return true
1042		})
1043		return stats
1044	}
