1104	func (q *inboundQueue) enqueue(
1105		peerID string,
1106		envelope Envelope,
1107		promptMode string,
1108		acceptedAt time.Time,
1109		prompting bool,
1110	) enqueueResult {
1111		q.mu.Lock()
1112		defer q.mu.Unlock()
1113	
1114		var dropped *Envelope
1115		wasEmpty := len(q.items) == 0
1116		if len(q.items) >= q.maxDepth {
1117			evicted := cloneEnvelope(q.items[0].Envelope)
1118			dropped = &evicted
1119			copy(q.items[0:], q.items[1:])
1120			q.items = q.items[:len(q.items)-1]
1121		}
1122		deliveryMode := "queued"
1123		if !prompting && wasEmpty {
1124			deliveryMode = "immediate"
1125		}
1126		q.items = append(q.items, queuedEnvelope{
1127			Envelope:     cloneEnvelope(envelope),
1128			PeerID:       strings.TrimSpace(peerID),
1129			AcceptedAt:   acceptedAt.UTC(),
1130			DeliveryMode: deliveryMode,
1131			PromptMode:   strings.TrimSpace(promptMode),
1132			SessionToken: q.token,
1133		})
1134	
1135		return enqueueResult{
1136			Depth:        len(q.items),
1137			DeliveryMode: deliveryMode,
1138			Dropped:      dropped,
1139		}
1140	}
