1213	func deliveredPromptCostAllocations(items []queuedEnvelope, total deliveredPromptCost) []deliveredPromptCost {
1214		if len(items) == 0 {
1215			return nil
1216		}
1217		weights := make([]int64, 0, len(items))
1218		var totalWeight int64
1219		for _, item := range items {
1220			weight := digestCostWeight(item.Envelope)
1221			if weight <= 0 {
1222				weight = 1
1223			}
1224			weights = append(weights, weight)
1225			totalWeight += weight
1226		}
1227		if totalWeight <= 0 {
1228			totalWeight = int64(len(items))
1229			for idx := range weights {
1230				weights[idx] = 1
1231			}
1232		}
1233		out := make([]deliveredPromptCost, len(items))
1234		var allocatedBytes int64
1235		var allocatedTokens int64
1236		for idx, weight := range weights {
1237			if idx == len(items)-1 {
1238				out[idx] = deliveredPromptCost{
1239					PromptSizeBytes:       total.PromptSizeBytes - allocatedBytes,
1240					EstimatedPromptTokens: total.EstimatedPromptTokens - allocatedTokens,
1241				}
1242				break
1243			}
1244			promptBytes := total.PromptSizeBytes * weight / totalWeight
1245			promptTokens := total.EstimatedPromptTokens * weight / totalWeight
1246			out[idx] = deliveredPromptCost{
1247				PromptSizeBytes:       promptBytes,
1248				EstimatedPromptTokens: promptTokens,
1249			}
1250			allocatedBytes += promptBytes
1251			allocatedTokens += promptTokens
1252		}
1253		return out
1254	}
1255	
1256	func digestCostWeight(envelope Envelope) int64 {
1257		deliveryBody, err := networkDeliveryBodyForEnvelope(envelope)
1258		if err != nil {
1259			return max(int64(len(envelope.Body)), 1)
1260		}
