1311	func networkDeliveryBodyForEnvelope(envelope Envelope) (networkDeliveryBody, error) {
1312		body, err := envelope.DecodeBody()
1313		switch {
1314		case err == nil:
1315			if say, ok := body.(SayBody); ok && len(say.Artifacts) == 0 {
1316				return networkDeliveryBody{
1317					preview:       strings.TrimSpace(say.Text),
1318					plainTextBody: say.Text,
1319				}, nil
1320			}
1321			canonicalBody, marshalErr := json.Marshal(body)
1322			if marshalErr != nil {
1323				return networkDeliveryBody{}, fmt.Errorf("network: marshal canonical body for delivery: %w", marshalErr)
1324			}
1325			return networkDeliveryBody{
1326				preview:       previewForBody(body),
1327				canonicalBody: canonicalBody,
1328			}, nil
1329		case !json.Valid(envelope.Body):
1330			return networkDeliveryBody{}, fmt.Errorf("network: decode envelope body for delivery: %w", err)
1331		default:
1332			var compact bytes.Buffer
1333			if compactErr := json.Compact(&compact, envelope.Body); compactErr != nil {
1334				return networkDeliveryBody{}, fmt.Errorf("network: compact raw envelope body for delivery: %w", compactErr)
1335			}
1336			return networkDeliveryBody{canonicalBody: compact.Bytes()}, nil
1337		}
1338	}
