1361	func formatNetworkMessageWithDeliveryModeAndLimit(
1362		envelope Envelope,
1363		guidanceMode networkMessageGuidanceMode,
1364		deliveryMode string,
1365		structuredBodyMaxBytes int,
1366	) (string, error) {
1367		if normalizePromptDeliveryMode(deliveryMode) == store.NetworkSubscriptionModeDigest {
1368			return formatNetworkDigestMessage(envelope, guidanceMode)
1369		}
1370	
1371		deliveryBody, err := networkDeliveryBodyForEnvelope(envelope)
1372		if err != nil {
1373			return "", err
1374		}
1375		encodedBody := ""
1376		structuredBodyTruncated := false
1377		originalBodyBytes := len(deliveryBody.canonicalBody)
1378		deliveredBodyBytes := originalBodyBytes
1379		if deliveryBody.plainTextBody == "" {
1380			cappedBody, truncated, capErr := cappedStructuredDeliveryBody(deliveryBody, structuredBodyMaxBytes)
1381			if capErr != nil {
1382				return "", capErr
1383			}
1384			structuredBodyTruncated = truncated
1385			deliveredBodyBytes = len(cappedBody)
1386			encodedBody = base64.StdEncoding.EncodeToString(cappedBody)
1387		}
1388	
1389		var builder strings.Builder
1390		builder.Grow(
1391			base64.StdEncoding.EncodedLen(len(deliveryBody.canonicalBody)) +
1392				len(deliveryBody.preview)*6 +
1393				len(deliveryBody.plainTextBody)*2 +
1394				2048,
1395		)
1396		builder.WriteString("<network-message")
1397		writeNetworkMessageAttrs(&builder, envelope, "")
1398		builder.WriteString(">\n")
1399		if deliveryBody.preview != "" {
1400			builder.WriteString("  <network-preview encoding=\"xml-escaped\">")
1401			builder.WriteString(xmlEscape(deliveryBody.preview))
1402			builder.WriteString("</network-preview>\n")
1403		}
1404		if deliveryBody.plainTextBody != "" {
1405			builder.WriteString("  <network-body encoding=\"text\">")
1406			builder.WriteString(xmlEscape(deliveryBody.plainTextBody))
1407			builder.WriteString("</network-body>\n")
1408		} else {
1409			builder.WriteString("  <network-body encoding=\"base64-json\">")
1410			builder.WriteString(encodedBody)
1411			builder.WriteString("</network-body>\n")
1412			if structuredBodyTruncated {
1413				builder.WriteString("  <network-body-truncated")
1414				writeXMLAttr(&builder, "original-bytes", strconv.Itoa(originalBodyBytes))
1415				writeXMLAttr(&builder, "delivered-bytes", strconv.Itoa(deliveredBodyBytes))
1416				builder.WriteString(">true</network-body-truncated>\n")
1417			}
1418		}
1419		builder.WriteString("</network-message>")
1420		writeReplyGuidance(&builder, envelope, guidanceMode)
1421	
1422		return builder.String(), nil
1423	}
