1425	func cappedStructuredDeliveryBody(
1426		deliveryBody networkDeliveryBody,
1427		maxBytes int,
1428	) ([]byte, bool, error) {
1429		if maxBytes <= 0 || len(deliveryBody.canonicalBody) <= maxBytes {
1430			return deliveryBody.canonicalBody, false, nil
1431		}
1432		truncated := struct {
1433			Truncated     bool   `json:"truncated"`
1434			OriginalBytes int    `json:"original_bytes"`
1435			DeliveredMax  int    `json:"delivered_max_bytes"`
1436			Preview       string `json:"preview,omitempty"`
1437		}{
1438			Truncated:     true,
1439			OriginalBytes: len(deliveryBody.canonicalBody),
1440			DeliveredMax:  maxBytes,
1441			Preview:       strings.TrimSpace(deliveryBody.preview),
1442		}
1443		payload, err := json.Marshal(truncated)
1444		if err != nil {
1445			return nil, false, fmt.Errorf("network: marshal truncated delivery body: %w", err)
1446		}
1447		if len(payload) > maxBytes {
1448			truncated.Preview = ""
1449			payload, err = json.Marshal(truncated)
1450			if err != nil {
1451				return nil, false, fmt.Errorf("network: marshal minimal truncated delivery body: %w", err)
1452			}
1453		}
1454		if len(payload) > maxBytes {
1455			minimal := []byte(`{"truncated":true}`)
1456			if len(minimal) <= maxBytes {
1457				return minimal, true, nil
1458			}
1459			return []byte(`0`), true, nil
1460		}
1461		return payload, true, nil
1462	}
