1471	func formatNetworkDigestBatchMessage(
1472		envelopes []Envelope,
1473		guidanceMode networkMessageGuidanceMode,
1474	) (string, error) {
1475		if len(envelopes) == 0 {
1476			return "", errors.New("network: digest batch is empty")
1477		}
1478		if len(envelopes) == 1 {
1479			return formatSingleNetworkDigestMessage(envelopes[0], guidanceMode)
1480		}
1481		type digestPreview struct {
1482			envelope Envelope
1483			preview  string
1484		}
1485		previews := make([]digestPreview, 0, len(envelopes))
1486		var previewBytes int
1487		for _, envelope := range envelopes {
1488			preview, err := networkDigestPreview(envelope)
1489			if err != nil {
1490				return "", err
1491			}
1492			previews = append(previews, digestPreview{envelope: envelope, preview: preview})
1493			previewBytes += len(preview)
1494		}
1495	
1496		first := envelopes[0]
1497		var builder strings.Builder
1498		builder.Grow(previewBytes*6 + len(envelopes)*512 + 1024)
1499		builder.WriteString("<network-digest-batch")
1500		writeNetworkMessageAttrs(&builder, first, store.NetworkSubscriptionModeDigest)
1501		writeXMLAttr(&builder, "count", strconv.Itoa(len(envelopes)))
1502		builder.WriteString(">\n")
1503		for _, item := range previews {
1504			builder.WriteString("  <network-digest-message")
1505			writeNetworkMessageAttrs(&builder, item.envelope, "")
1506			builder.WriteString(" encoding=\"xml-escaped\">")
1507			builder.WriteString(xmlEscape(item.preview))
1508			builder.WriteString("</network-digest-message>\n")
1509		}
1510		builder.WriteString("</network-digest-batch>")
1511		writeReplyGuidance(&builder, first, guidanceMode)
1512		return builder.String(), nil
1513	}
1514	
1515	func formatSingleNetworkDigestMessage(
1516		envelope Envelope,
1517		guidanceMode networkMessageGuidanceMode,
1518	) (string, error) {
1519		preview, err := networkDigestPreview(envelope)
1520		if err != nil {
1521			return "", err
1522		}
1523	
1524		var builder strings.Builder
1525		builder.Grow(len(preview)*6 + 1024)
1526		builder.WriteString("<network-message")
1527		writeNetworkMessageAttrs(&builder, envelope, store.NetworkSubscriptionModeDigest)
1528		builder.WriteString(">\n")
1529		builder.WriteString("  <network-digest encoding=\"xml-escaped\">")
1530		builder.WriteString(xmlEscape(preview))
1531		builder.WriteString("</network-digest>\n")
1532		builder.WriteString("</network-message>")
1533		writeReplyGuidance(&builder, envelope, guidanceMode)
1534		return builder.String(), nil
1535	}
