1537	func networkDigestPreview(envelope Envelope) (string, error) {
1538		body, err := envelope.DecodeBody()
1539		preview := ""
1540		switch {
1541		case err == nil:
1542			preview = previewForBody(body)
1543		case !json.Valid(envelope.Body):
1544			return "", fmt.Errorf("network: decode envelope body for digest delivery: %w", err)
1545		default:
1546			var compact bytes.Buffer
1547			if compactErr := json.Compact(&compact, envelope.Body); compactErr != nil {
1548				return "", fmt.Errorf("network: compact raw envelope body for digest delivery: %w", compactErr)
1549			}
1550			preview = compact.String()
1551		}
1552		preview = strings.TrimSpace(preview)
1553		if preview == "" {
1554			preview = string(envelope.Kind)
1555		}
1556		return preview, nil
1557	}
