1075				delta = afterMemory.Alloc - baselineMemory.Alloc
1076			}
1077			if delta > 200*1024*1024 {
1078				t.Fatalf("heap allocation delta after flood = %d bytes, want < 200 MiB", delta)
1079			}
1080			waitForCondition(waitCtx, t, func() bool {
