20	func TestInboundQueuePreservesFIFOAndDropsOldestOnOverflow(t *testing.T) {
21		t.Parallel()
22	
23		queue := newInboundQueue(2)
24		first := testDeliveryEnvelope(t, "msg-1", "first")
25		second := testDeliveryEnvelope(t, "msg-2", "second")
26		third := testDeliveryEnvelope(t, "msg-3", "third")
27		now := time.Date(2026, 4, 11, 13, 0, 0, 0, time.UTC)
28	
29		if result := queue.enqueue(
30			"peer-one",
31			first,
32			store.NetworkSubscriptionModeFull,
33			now,
34			false,
35		); result.Dropped != nil ||
36			result.Depth != 1 {
37			t.Fatalf("enqueue(first) = %#v, want depth=1 with no drop", result)
38		}
39		if result := queue.enqueue(
40			"peer-two",
41			second,
42			store.NetworkSubscriptionModeFull,
43			now.Add(time.Second),
44			false,
45		); result.Dropped != nil || result.Depth != 2 {
46			t.Fatalf("enqueue(second) = %#v, want depth=2 with no drop", result)
47		}
48		if result := queue.enqueue(
49			"peer-three",
50			third,
51			store.NetworkSubscriptionModeFull,
52			now.Add(2*time.Second),
53			true,
54		); result.Dropped == nil || result.Dropped.ID != first.ID ||
55			result.Depth != 2 {
56			t.Fatalf("enqueue(third) = %#v, want drop=%q depth=2", result, first.ID)
57		}
58	
59		gotFirst, ok := queue.dequeue()
60		if !ok {
61			t.Fatal("dequeue(first) = missing, want second envelope")
62		}
63		gotSecond, ok := queue.dequeue()
64		if !ok {
65			t.Fatal("dequeue(second) = missing, want third envelope")
66		}
67		if _, ok := queue.dequeue(); ok {
68			t.Fatal("dequeue(third) = present, want queue empty")
69		}
70	
71		if gotFirst.Envelope.ID != second.ID {
72			t.Fatalf("first dequeue id = %q, want %q", gotFirst.Envelope.ID, second.ID)
73		}
74		if gotSecond.Envelope.ID != third.ID {
75			t.Fatalf("second dequeue id = %q, want %q", gotSecond.Envelope.ID, third.ID)
76		}
77		if gotFirst.Envelope.WorkspaceID != testWorkspaceID {
78			t.Fatalf("first dequeue workspace_id = %q, want %q", gotFirst.Envelope.WorkspaceID, testWorkspaceID)
79		}
80		if gotSecond.Envelope.WorkspaceID != testWorkspaceID {
81			t.Fatalf("second dequeue workspace_id = %q, want %q", gotSecond.Envelope.WorkspaceID, testWorkspaceID)
82		}
83		if gotFirst.PeerID != "peer-two" {
84			t.Fatalf("first dequeue peer_id = %q, want peer-two", gotFirst.PeerID)
85		}
86		if gotSecond.PeerID != "peer-three" {
87			t.Fatalf("second dequeue peer_id = %q, want peer-three", gotSecond.PeerID)
88		}
89	}
