220	func ensureSchemaMigrationsTable(ctx context.Context, db *sql.DB, table string) (err error) {
221		tx, err := db.BeginTx(ctx, nil)
222		if err != nil {
223			return fmt.Errorf("store: begin schema migrations bootstrap: %w", err)
224		}
225		defer rollbackMigrationTx(&err, tx, "schema migrations bootstrap")
226	
227		quotedTable := quoteIdentifier(table)
228		if _, err := tx.ExecContext(ctx, fmt.Sprintf(`CREATE TABLE IF NOT EXISTS %s (
229			version    INTEGER PRIMARY KEY,
230			name       TEXT NOT NULL,
231			checksum   TEXT NOT NULL,
232			applied_at TEXT NOT NULL
233		);`, quotedTable)); err != nil {
234			return fmt.Errorf("store: create schema_migrations table: %w", err)
235		}
236		indexName := quoteIdentifier("idx_" + table + "_name")
237		if _, err := tx.ExecContext(ctx, fmt.Sprintf(`
238			CREATE UNIQUE INDEX IF NOT EXISTS %s
239			ON %s(name);
240		`, indexName, quotedTable)); err != nil {
241			return fmt.Errorf("store: create schema_migrations name index: %w", err)
242		}
243		if err := tx.Commit(); err != nil {
244			return fmt.Errorf("store: commit schema migrations bootstrap: %w", err)
245		}
246		return nil
247	}
