277	func validateAppliedMigrationRecords(applied map[int]MigrationRecord, expected map[int]MigrationRecord) error {
278		versions := make([]int, 0, len(applied))
279		for version := range applied {
280			versions = append(versions, version)
281		}
282		sort.Ints(versions)
283		for _, version := range versions {
284			record := applied[version]
285			current, ok := expected[version]
286			if !ok {
287				return fmt.Errorf(
288					"store: applied migration %d %q is not present in current registry",
289					record.Version,
290					record.Name,
291				)
292			}
293			if record.Name != current.Name || record.Checksum != current.Checksum {
294				return fmt.Errorf(
295					"store: migration %d integrity mismatch: recorded %q/%s, current %q/%s",
296					record.Version,
297					record.Name,
298					record.Checksum,
299					current.Name,
300					current.Checksum,
301				)
302			}
303		}
304		return nil
