349	// applyConnMigration runs a UpConn migration on a dedicated connection (outside any
350	// wrapping transaction so the migration can toggle PRAGMA foreign_keys), then records it.
351	// The migration body owns its own inner transaction and foreign-key restoration.
352	func applyConnMigration(
353		ctx context.Context,
354		db *sql.DB,
355		table string,
356		migration Migration,
357		checksum string,
358	) (err error) {
359		name := strings.TrimSpace(migration.Name)
360		conn, err := db.Conn(ctx)
361		if err != nil {
362			return fmt.Errorf("store: open connection for migration %d %q: %w", migration.Version, name, err)
363		}
364		defer func() {
365			if closeErr := conn.Close(); closeErr != nil {
366				closeErr = fmt.Errorf(
367					"store: close connection for migration %d %q: %w",
368					migration.Version,
369					name,
370					closeErr,
371				)
372				if err == nil {
373					err = closeErr
374					return
375				}
376				err = errors.Join(err, closeErr)
377			}
378		}()
379		if err := migration.UpConn(ctx, conn); err != nil {
380			return fmt.Errorf("store: apply migration %d %q: %w", migration.Version, name, err)
381		}
382		if _, err := conn.ExecContext(
383			ctx,
384			fmt.Sprintf(`INSERT INTO %s (version, name, checksum, applied_at) VALUES (?, ?, ?, ?)`, quoteIdentifier(table)),
385			migration.Version,
386			name,
387			checksum,
388			FormatTimestamp(time.Now().UTC()),
389		); err != nil {
390			return fmt.Errorf("store: record migration %d %q: %w", migration.Version, name, err)
391		}
392		return nil
393	}
394	
395	func migrationChecksum(migration Migration) (string, error) {
396		if checksum := strings.TrimSpace(migration.Checksum); checksum != "" {
397			return checksum, nil
398		}
399		name := strings.TrimSpace(migration.Name)
400		if len(migration.Statements) == 0 {
401			return "", fmt.Errorf(
402				"store: migration %d %q checksum is required for custom operation",
403				migration.Version,
404				name,
405			)
406		}
407	
408		hash := sha256.New()
409		if _, err := fmt.Fprintf(hash, "%d\n%s\n", migration.Version, name); err != nil {
410			return "", fmt.Errorf(
411				"store: hash migration %d %q header: %w",
412				migration.Version,
413				name,
414				err,
415			)
416		}
417		for _, statement := range migration.Statements {
418			if _, err := hash.Write([]byte(strings.TrimSpace(statement))); err != nil {
419				return "", fmt.Errorf(
420					"store: hash migration %d %q statement: %w",
421					migration.Version,
422					name,
423					err,
424				)
425			}
426			if _, err := hash.Write([]byte{'\n'}); err != nil {
427				return "", fmt.Errorf(
428					"store: hash migration %d %q separator: %w",
429					migration.Version,
430					name,
431					err,
432				)
433			}
434		}
435		return hex.EncodeToString(hash.Sum(nil)), nil
436	}
437	
438	func appliedMigrations(ctx context.Context, db *sql.DB, table string) (records []MigrationRecord, err error) {
439		if ctx == nil {
440			return nil, errors.New("store: list schema migrations context is required")
441		}
442		if db == nil {
443			return nil, errors.New("store: list schema migrations database is required")
444		}
445		normalizedTable, err := normalizeMigrationTableName(table)
446		if err != nil {
447			return nil, err
448		}
449		exists, err := migrationTableExists(ctx, db, normalizedTable)
450		if err != nil {
451			return nil, err
452		}
453		if !exists {
454			return nil, nil
455		}
456	
457		rows, err := db.QueryContext(
458			ctx,
459			fmt.Sprintf(`
460			SELECT version, name, checksum, applied_at
461			FROM %s
462			ORDER BY version ASC
463		`, quoteIdentifier(normalizedTable)),
464		)
465		if err != nil {
466			return nil, fmt.Errorf("store: query schema migrations: %w", err)
467		}
468		defer func() {
469			if closeErr := rows.Close(); closeErr != nil {
470				closeErr = fmt.Errorf("store: close schema migration rows: %w", closeErr)
471				if err == nil {
472					err = closeErr
473					return
474				}
475				err = errors.Join(err, closeErr)
476			}
477		}()
478	
479		records = make([]MigrationRecord, 0)
480		for rows.Next() {
481			var (
482				record     MigrationRecord
483				appliedRaw string
484			)
485			if err := rows.Scan(&record.Version, &record.Name, &record.Checksum, &appliedRaw); err != nil {
486				return nil, fmt.Errorf("store: scan schema migration: %w", err)
487			}
488			appliedAt, err := ParseTimestamp(appliedRaw)
489			if err != nil {
490				return nil, fmt.Errorf("store: parse schema migration timestamp: %w", err)
491			}
492			record.AppliedAt = appliedAt
493			records = append(records, record)
494		}
495		if err := rows.Err(); err != nil {
496			return nil, fmt.Errorf("store: iterate schema migrations: %w", err)
497		}
498		return records, nil
499	}
500	
501	func migrationTableExists(ctx context.Context, db *sql.DB, table string) (bool, error) {
502		var count int
503		if err := db.QueryRowContext(
504			ctx,
505			`SELECT COUNT(*) FROM sqlite_master WHERE type = 'table' AND name = ?`,
506			table,
507		).Scan(&count); err != nil {
508			return false, fmt.Errorf("store: query schema_migrations table: %w", err)
509		}
510		return count > 0, nil
511	}
512	
513	func rollbackMigrationTx(target *error, tx *sql.Tx, action string) {
514		if tx == nil || target == nil {
515			return
516		}
517		if err := tx.Rollback(); err != nil && !errors.Is(err, sql.ErrTxDone) {
518			rollbackErr := fmt.Errorf("store: rollback %s: %w", action, err)
519			if *target == nil {
520				*target = rollbackErr
521				return
522			}
523			*target = errors.Join(*target, rollbackErr)
524		}
525	}
