307	func applyMigration(ctx context.Context, db *sql.DB, table string, migration Migration, checksum string) (err error) {
308		if migration.UpConn != nil {
309			return applyConnMigration(ctx, db, table, migration, checksum)
310		}
311		name := strings.TrimSpace(migration.Name)
312		tx, err := db.BeginTx(ctx, nil)
313		if err != nil {
314			return fmt.Errorf("store: begin migration %d %q: %w", migration.Version, name, err)
315		}
316		defer rollbackMigrationTx(&err, tx, fmt.Sprintf("migration %d %q", migration.Version, name))
317	
318		if migration.Up != nil {
319			if err := migration.Up(ctx, tx); err != nil {
320				return fmt.Errorf("store: apply migration %d %q: %w", migration.Version, name, err)
321			}
322		} else {
323			for _, statement := range migration.Statements {
324				if err := ctx.Err(); err != nil {
325					return fmt.Errorf("store: apply migration %d %q: %w", migration.Version, name, err)
326				}
327				if _, err := tx.ExecContext(ctx, statement); err != nil {
328					return fmt.Errorf("store: apply migration %d %q: %w", migration.Version, name, err)
329				}
330			}
331		}
332	
333		if _, err := tx.ExecContext(
334			ctx,
335			fmt.Sprintf(`INSERT INTO %s (version, name, checksum, applied_at) VALUES (?, ?, ?, ?)`, quoteIdentifier(table)),
336			migration.Version,
337			name,
338			checksum,
339			FormatTimestamp(time.Now().UTC()),
340		); err != nil {
341			return fmt.Errorf("store: record migration %d %q: %w", migration.Version, name, err)
342		}
343		if err := tx.Commit(); err != nil {
344			return fmt.Errorf("store: commit migration %d %q: %w", migration.Version, name, err)
345		}
346		return nil
347	}
