421	func presetEventFromTaskRecord(
422		ctx context.Context,
423		tasks bridgepkg.TerminalTaskEventReader,
424		record taskpkg.EventRecord,
425		logger *slog.Logger,
426	) presetspkg.Event {
427		event := presetspkg.Event{
428			ID:        strings.TrimSpace(record.Event.ID),
429			Type:      strings.TrimSpace(record.Event.EventType),
430			AgentName: strings.TrimSpace(record.Event.Actor.Ref),
431			TaskID:    strings.TrimSpace(record.Event.TaskID),
432			RunID:     strings.TrimSpace(record.Event.RunID),
433			Outcome:   eventspkg.OutcomeFor(record.Event.EventType),
434			Sequence:  record.Sequence,
435			Payload:   append([]byte(nil), record.Event.Payload...),
436			Timestamp: record.Event.Timestamp,
437		}
438		if tasks != nil && event.TaskID != "" {
439			taskRecord, err := tasks.GetTask(ctx, event.TaskID)
440			if err == nil {
441				event.WorkspaceID = strings.TrimSpace(taskRecord.WorkspaceID)
442				event.Summary = strings.TrimSpace(taskRecord.Title)
443			} else if logger != nil {
444				logger.Debug(
445					"daemon: notification preset could not enrich task event",
446					"task_id", event.TaskID,
447					"event_id", event.ID,
448					"error", err,
449				)
450			}
451		}
452		return event
453	}
