248				req.To = strings.TrimSpace(direct.PeerB)
249				return nil
250			case strings.TrimSpace(direct.PeerB):
251				req.To = strings.TrimSpace(direct.PeerA)
252				return nil
253			default:
254				return fmt.Errorf(
255					"%w: session peer %q is not part of direct room %q",
256					network.ErrInvalidField,
257					peerID,
258					directID,
259				)
260			}
261		}
262		return fmt.Errorf(
263			"%w: session=%q channel=%q",
264			network.ErrLocalPeerNotFound,
265			sessionID,
266			channel,
267		)
268	}
