270	// NetworkInbox returns the queued inbound envelopes for one local session.
271	func (h *BaseHandlers) NetworkInbox(c *gin.Context) {
272		service, err := h.networkServiceRequired()
273		if err != nil {
274			h.respondError(c, http.StatusServiceUnavailable, err)
275			return
276		}
277		scope, ok := h.resolveWorkspaceScope(c)
278		if !ok {
279			return
280		}
281	
282		sessionID := strings.TrimSpace(c.Query("session_id"))
283		if sessionID == "" {
284			sessionID = strings.TrimSpace(c.Query("session"))
285		}
286		if sessionID == "" {
287			h.respondError(c, http.StatusBadRequest, NewNetworkValidationError(errors.New("session_id query is required")))
288			return
289		}
290		if _, err := h.requireSessionInWorkspace(c.Request.Context(), scope.SessionWorkspaceID(), sessionID); err != nil {
291			h.respondError(c, statusForWorkspaceScopedResourceError(err), err)
292			return
293		}
294	
295		messages, err := service.Inbox(c.Request.Context(), sessionID)
296		if err != nil {
297			h.respondError(c, StatusForNetworkError(err), err)
298			return
299		}
300		c.JSON(http.StatusOK, contract.NetworkInboxResponse{Messages: NetworkEnvelopePayloadsFromEnvelopes(messages)})
301	}
