348	// NetworkSendRequestFromPayload validates and converts one shared send payload into the runtime request.
349	func NetworkSendRequestFromPayload(req contract.NetworkSendRequest) (network.SendRequest, error) {
350		if strings.TrimSpace(req.SessionID) == "" {
351			return network.SendRequest{}, NewNetworkValidationError(errors.New("session_id is required"))
352		}
353		if strings.TrimSpace(req.WorkspaceID) == "" {
354			return network.SendRequest{}, NewNetworkValidationError(errors.New("workspace_id is required"))
355		}
356		if strings.TrimSpace(req.Channel) == "" {
357			return network.SendRequest{}, NewNetworkValidationError(errors.New("channel is required"))
358		}
359		if strings.TrimSpace(req.Kind) == "" {
360			return network.SendRequest{}, NewNetworkValidationError(errors.New("kind is required"))
361		}
362		if len(bytes.TrimSpace(req.Body)) == 0 {
363			return network.SendRequest{}, NewNetworkValidationError(errors.New("body is required"))
364		}
365		if !json.Valid(req.Body) {
366			return network.SendRequest{}, NewNetworkValidationError(errors.New("body must be valid JSON"))
367		}
368		if err := validateNetworkSendNoRawClaimToken(req); err != nil {
369			return network.SendRequest{}, err
370		}
371		if err := validateNetworkSendConversation(req); err != nil {
372			return network.SendRequest{}, err
373		}
374	
375		sendReq := network.SendRequest{
376			SessionID:   strings.TrimSpace(req.SessionID),
377			WorkspaceID: strings.TrimSpace(req.WorkspaceID),
378			Channel:     strings.TrimSpace(req.Channel),
379			Kind:        network.Kind(strings.TrimSpace(req.Kind)),
380			Body:        cloneRawMessage(req.Body),
381			Mentions:    cloneTrimmedStrings(req.Mentions),
382			ExpiresAt:   cloneInt64Ptr(req.ExpiresAt),
383			Ext:         cloneRawMap(req.Ext),
384		}
385		if to := strings.TrimSpace(req.To); to != "" {
386			sendReq.To = ptrString(to)
387		}
388		if surface := strings.TrimSpace(req.Surface); surface != "" {
389			networkSurface := network.Surface(surface)
390			sendReq.Surface = &networkSurface
391		}
392		if threadID := strings.TrimSpace(req.ThreadID); threadID != "" {
393			sendReq.ThreadID = ptrString(threadID)
394		}
395		if directID := strings.TrimSpace(req.DirectID); directID != "" {
396			sendReq.DirectID = ptrString(directID)
397		}
398		if workID := strings.TrimSpace(req.WorkID); workID != "" {
399			sendReq.WorkID = ptrString(workID)
400		}
401		if replyTo := strings.TrimSpace(req.ReplyTo); replyTo != "" {
402			sendReq.ReplyTo = ptrString(replyTo)
403		}
404		if traceID := strings.TrimSpace(req.TraceID); traceID != "" {
405			sendReq.TraceID = ptrString(traceID)
406		}
407		if causationID := strings.TrimSpace(req.CausationID); causationID != "" {
408			sendReq.CausationID = ptrString(causationID)
409		}
410		if id := strings.TrimSpace(req.ID); id != "" {
411			sendReq.ID = ptrString(id)
412		}
413	
414		return sendReq, nil
415	}
