417	func validateNetworkSendConversation(req contract.NetworkSendRequest) error {
418		kind := network.Kind(strings.TrimSpace(req.Kind))
419		if err := kind.Validate(); err != nil {
420			return NewNetworkValidationError(err)
421		}
422	
423		surface := strings.TrimSpace(req.Surface)
424		threadID := strings.TrimSpace(req.ThreadID)
425		directID := strings.TrimSpace(req.DirectID)
426		workID := strings.TrimSpace(req.WorkID)
427		if kind == network.KindGreet || kind == network.KindWhois {
428			if surface != "" || threadID != "" || directID != "" || workID != "" {
429				return NewNetworkValidationError(fmt.Errorf(
430					"%w: %s cannot carry conversation or work fields",
431					network.ErrInvalidField,
432					kind,
433				))
434			}
435			return nil
436		}
437	
438		if surface == "" {
439			return NewNetworkValidationError(fmt.Errorf("%w: surface is required", network.ErrMissingField))
440		}
441		ref := network.ConversationRef{
442			WorkspaceID: strings.TrimSpace(req.WorkspaceID),
443			Channel:     strings.TrimSpace(req.Channel),
444			Surface:     network.Surface(surface),
445			ThreadID:    threadID,
446			DirectID:    directID,
447		}
448		if err := ref.Validate(); err != nil {
449			return NewNetworkValidationError(err)
450		}
451		if workID != "" {
452			if err := network.ValidateWorkID(workID); err != nil {
453				return NewNetworkValidationError(err)
454			}
455		}
456		if kind == network.KindCapability || kind == network.KindReceipt || kind == network.KindTrace {
457			if workID == "" {
458				return NewNetworkValidationError(fmt.Errorf("%w: work_id is required", network.ErrMissingField))
459			}
460		}
461		return nil
462	}
