584	func networkPresenceFields(peer network.PeerInfo) (string, *int64) {
585		state := string(peer.PresenceState)
586		if state == "" && peer.Local {
587			state = contract.NetworkPresenceLocal
588		}
589		switch state {
590		case contract.NetworkPresenceLocal,
591			contract.NetworkPresenceActive,
592			contract.NetworkPresenceInactive,
593			contract.NetworkPresenceExpired,
594			contract.NetworkPresenceUnknown:
595		default:
596			state = contract.NetworkPresenceUnknown
597		}
598		if state == contract.NetworkPresenceLocal || state == contract.NetworkPresenceUnknown {
599			return state, nil
600		}
601		return state, cloneInt64Ptr(peer.LastSeenAgeSeconds)
602	}
