648		capabilityCatalog []session.NetworkPeerCapability,
649	) []contract.NetworkCapabilityBriefPayload {
650		summaries := decodeCapabilityBriefSummaries(card.Ext)
651		if len(capabilityCatalog) > 0 {
652			orderedIDs := card.Capabilities
653			if len(orderedIDs) == 0 {
654				orderedIDs = make([]string, 0, len(capabilityCatalog))
655				for _, capability := range capabilityCatalog {
656					orderedIDs = append(orderedIDs, capability.ID)
657				}
658			}
659	
660			if summaries == nil {
