662			}
663			for _, capability := range capabilityCatalog {
664				id := strings.TrimSpace(capability.ID)
665				if id == "" {
666					continue
667				}
668				summaries[id] = strings.TrimSpace(capability.Summary)
669			}
670			return capabilityBriefPayloadsFromIDs(orderedIDs, summaries)
671		}
672	
673		return capabilityBriefPayloadsFromIDs(card.Capabilities, summaries)
674	}
